        "chinese": "许多研究的结果乍看之下“很单薄”。有位经营学者设定目标：用统计方法测定在德国境内乘汽车最容易到达 的会面地点。经过 70 页计算，他建议最好在莱茵/美因地区见面，而不是在吕根岛。另一篇论文分析连续剧 爱的风暴》，得出结论说，“爱”可以被确认为其主导主题。很容易受到这样的指责：把人人皆知的东西加 上几条脚注就“封爵”为所谓的学术证据——但这是一个误解。对毕业论文而言，比“新发现”更重要的是： 向学生发起挑战——放下“想当然的确定性”，培养批判立场。",
