        "chinese": "大学有义务把毕业论文保存若干年，之后粉碎处理。我桌上的这些副本是“漏网之鱼”：它们要么是在某位好 心教授的推荐下得以出版，要么就是人们不仅把论文，还把它们的保留期限也给忘了。毕业论文是学术运行的 副产物。正因为如此，它们作为时代文献才有价值；就像考古学家从文明废墟的垃圾堆里获得的认识，往往多 于从它们的宫殿里得到的。对很多人而言，毕业论文是他们一生中写得最长的文本；它们常常出于某种非常私 人的诉求。只有这样，人才可以解释为何会对部分离奇题目产生兴趣——例如，有一篇论文写的是若干重要经 济作物的迷人之处。",
