        "passage": "Die Universitäten sind verpflichtet, Abschlussarbeiten einige Jahre aufzubewahren, danach werden sie geschreddret. Die Exemplare auf meinem Schreibtisch sind durch das Raster gefallen. Sie wurden auf Empfehlung eines wohlwollenden Professors veröffentlicht, oder man hat nicht nur die Arbeiten sondern auch deren Schonfristen vergessen. Abschlussarbeiten sind das Abfallprodukt des akademischen Betriebs. Gerade das macht sie als Zeitdokumente wertvoll , auch Archäologen ziehen mehr Erkenntnisse aus den Müllhalden untergegangener Zivilisationen als aus deren Palästen, für viele Menschen und Abschlussarbeiten die längsten Texte, die sie in ihrem Leben schreiben oftmals liegt ihnen ein ganz privates Anliegen zu Grunde. Nur dadurch kann das Interesse an teils abwegigen Themen erklärt werden gibt eine Abschlussarbeit , über die Faszination hoher Bedeutung einiger Nutzgehölze.",
