        "chinese": "摆在我桌上的某些研究成果，乍看确实“单薄”——读的时候我也不时忍不住会心一笑。一位经营学者致力于 用统计方法测定在德国境内开车最容易到达的会面地点。整整 70 页、满满当当令人肃然起敬的计算之后，他 得出一个并非全无道理的建议：与其在吕根岛见面，不如在莱茵-美因地区见面。哎呀，我心想：不用复杂数学 我也能想到。另一篇论文分析肥皂剧《爱的风暴》，得出结论：“爱”可被确认为其上位主题。批评者提出指 责：毕业论文不过是给人尽皆知的东西加上几条脚注，便“晋升”为学术证据。但仔细一看，这是一个重大误 解：对毕业论文而言，比起“新发现”，更重要的一直是向学生发起挑战——放下“想当然的确定性”，培养 批判立场。只有当一个事实经过论证推导出来，年轻学者才可以相信并认可“常识”。这才是最纯粹意义上的 科学。",
        "sentenceZh": "摆在我桌上的某些研究成果，乍看确实“单薄”——读的时候我也不时忍不住会心一笑。",
        "summary": "摆在我桌上的某些研究成果，乍看确实“单薄”——读的时候我也不时忍不住会心一笑。",
        "passage": "Die Ergebnisse mancher Studien, die vor mir auf dem Schreibtisch liegen, sind auf den ersten Blick allerdings dürftig ↪ und beim Lesen kann ich mir nicht immer ein Lächeln verkneifen.. Ein Betriebswissenschaftler widmet sich dem Ziel, mittels eines statistischen Verfahrens zu ermitteln, welcher Standort innerhalb Deutschlands mit dem Auto am besten zu erreichen wäre. Nach ganzen 70 Seiten voll mit respekteinflößenden Berechnungen kommt er zu der sicher nicht ganz abwegigen Empfehlung, sich lieber im Rhein-Main- Gebiet als auf Rügen zu treffen. Na sowas, denke ich: Das hätte ich auch ohne komplizierte Mathematik herausgefunden. Eine andere Arbeit analysiert die Telenovela Sturm der Liebe und kommt zu dem Schluss, Liebe lasse sich als übergeordnetes Thema feststellen. Kritiker äußern den Vorwurf, allgemein Bekanntes würde in Abschlussarbeiten mit ein paar Fußnoten in den Adelsstand akademischer Evidenz gehoben. Aber bei näherem Hinsehen handelt es sich dabei um ein großes Missverständnis, denn wichtiger als neue Erkenntnisse war schon immer die Herausforderung an die Studenten, Gewissheiten aufzugeben und eine kritische Haltung zu entwickeln. Erst wenn ein Sachverhalt argumentativ hergeleitet wurde, darf der junge Akademiker dem gesunden Menschenverstand trauen und zustimmen. Das ist Wissenschaft in ihrer reinsten Form.",
