        "text": "Was für ein Schrecken!",
        "german": "Was für ein Schrecken!",
        "firstSentence": "Was für ein Schrecken!",
        "chinese": "多么吓人啊！刚收到自己中乐透的消息，闹钟却把你无情地从睡梦中拽醒，最大的希望一下子就化为乌有：突 如其来的横财到此为止——谁不想再躺回去多睡一会儿呢？在梦里经常发生离奇的事情。逻辑和自然法则被暂 停，我们能经历最疯狂的冒险：我们克服重力，像鸟一样飞上天空，在水下呼吸，或者不费吹灰之力来一场时 空旅行。我们常常又一次以变形的方式经历日常生活中的种种不顺。相反，在噩梦里，最大的恐惧会来纠缠我 们。一些夜间的惊吓场景还很普遍：被追赶、坠入无底深渊或丢尽颜面的梦，在跨文化范围内都广为人知。",
        "sentenceZh": "多么吓人啊！",
        "summary": "多么吓人啊！",
        "passage": "Was für ein Schrecken! Gerade bekamen Sie die Nachricht, im Lotto gewonnen zu haben , Und dann reißt Sie der Wecker grausam aus dem Schlaf und schlagartig verpuffen. die größten Hoffnungen: Mit dem plötzlichen Geldsegen ist es vorbei- Wer will sich da nicht lieber noch mal eine Runde aufs Ohr hauen? Im Traum passieren oft skurrile Dinge. Logik und Naturgesetze sind außer kraft gesetzt und wir können die verrücktesten Abenteuer erleben: Wir überwinden die Schwerkraft, erheben uns wie ein Vogel in die Lüge, atmen unter Wasser oder unternehmen mir nichts, dir nichts eine Zeitreise. Oft durchleben wir noch einmal in verfremdeter Form die Widrigkeiten des Alltags. In Alpträumen suchen uns dagegen unsere größten Ängste heim. Manche dieser nächtlichen Schreckensszenarien sind weiterverbreitet : Träume , in denen man verfolgt wird, ins Bodenlose stürzt oder sich hoffnungslos blamiert, sind über Kulturenzen hinweg bekannt.",
        "frage": "",
