        "text": "Ich bin Studentin und habe eine kleine Tochter.",
        "german": "Ich bin Studentin und habe eine kleine Tochter.",
        "firstSentence": "Ich bin Studentin und habe eine kleine Tochter.",
        "chinese": "我是女大学生，有个小女儿。她现在生病了：幼儿园的细菌。两天后她就会“重新点燃火箭推进器”。但我已 经完全撑不住了。一个极小的小孩病菌就能让我一周几乎下不了床。我现在知道什么是头疼和四肢疼：一群陌 生人从一辆贴了深色车膜的黑色轿车里走出来，挥舞棒球棒把我一顿狠揍。这些幼儿园病菌的阴险之处在于： 它们会同时感染孩子和大人中的一个。另一个人还能勉强站着，以便承担起照顾家庭的任务——在我们家，这 个人是我男朋友。我此时躺在沙发上，嘟囔着希望快点结束。",
        "sentenceZh": "我是女大学生，有个小女儿。",
        "summary": "我是女大学生，有个小女儿。",
        "passage": "Ich bin Studentin und habe eine kleine Tochter. Die ist zurzeit krank: Kitakeime. In zwei Tagen wird sie aber wieder ihren Raketenantrieb zünden. Nur ich bin völlig am Ende. Ein klitzekleiner Kinderkeim lässt mich eine Woche kaum aus dem Bett kommen. Ich weiß jetzt, was kopf und Gliederschmerzen sind: ein Haufen Unbekannter, die aus einer dunkeln Limousine mit Getönten Scheiben Steigen, ihren Baseballschläger zücken und auf mich einprügeln. Das perfide an diesem Kitakeimen ist, sie erwischen das Kind und einen der Erwachsenen. Der andere bleibt halbwegs auf den Beinen, damit er die Pflege der Familie in Angriff nehmen kann, und in diesem Fall ist das mein Freund. Ich liege derweil auf dem Sofa und wimmere nach einem raschen Ende.",
