        "number": "4",
        "paragraph": "D",
        "text": "Während ich hustend auf dem Sofa liege und über mein Leben nachdenke, habe ich diesen Werbespot im Kopf, der mir sagt, dass eine erkältete Mutter sich keine Auszeit nimmt, sondern ein Grippemittel, um sich dann glücklich lächelnd wieder ihren täglichen Aufgaben zu widmen.",
        "german": "Während ich hustend auf dem Sofa liege und über mein Leben nachdenke, habe ich diesen Werbespot im Kopf, der mir sagt, dass eine erkältete Mutter sich keine Auszeit nimmt, sondern ein Grippemittel, um sich dann glücklich lächelnd wieder ihren täglichen Aufgaben zu widmen.",
        "firstSentence": "Während ich hustend auf dem Sofa liege und über mein Leben nachdenke, habe ich diesen Werbespot im Kopf, der mir sagt, dass eine erkältete Mutter sich keine Auszeit nimmt, sondern ein Grippemittel, um sich dann glücklich lächelnd wieder ihren täglichen Aufgaben zu widmen.",
        "chinese": "我一边在沙发上咳嗽，一边思考我的生活，脑海里浮现一个广告：感冒了的妈妈不是休息，而是吃一粒感冒药， 然后笑容满面地继续日常任务。要理解这有多不必要，我只需要看看我的小家伙。她坐在地毯上，读她的《挖 掘机书》，指着各种清扫车和工程车；如果没有这本书，我永远不会知道它们的正确名称，比如“洒水车”和 滚装自卸车”。突然我明白：如果完美反而是愚蠢的，那就没什么可学的了：关于车辆、关于我的小家伙即 使像一只相当怪的青蛙也能享受狂欢节，以及她并不会因为我生病就更少叫我妈妈。",
        "sentenceZh": "我一边在沙发上咳嗽，一边思考我的生活，脑海里浮现一个广告：感冒了的妈妈不是休息，而是吃一粒感冒药， 然后笑容满面地继续日常任务。",
        "summary": "我一边在沙发上咳嗽，一边思考我的生活，脑海里浮现一个广告：感冒了的妈妈不是休息，而是吃一粒感冒药， 然后笑容满面地继续日常任务。",
        "passage": "Während ich hustend auf dem Sofa liege und über mein Leben nachdenke, habe ich diesen Werbespot im Kopf, der mir sagt, dass eine erkältete Mutter sich keine Auszeit nimmt, sondern ein Grippemittel, um sich dann glücklich lächelnd wieder ihren täglichen Aufgaben zu widmen. Um zu begreifen, wie unnötig das ist, muss ich nur meine Kleine anschauen. Die sitzt auf dem Teppich, liest ihr, Baggerbuch' und zeigt mir sämtliche Straßenreinigungs- und Baufahrzeuge. von denen ich ohne dieses Buch niemals die korrekten Bezeichnungen wie Wassertankwagen' und, Abrollkipper gewusst hatte, und plötzlich wird mir klar, dass es sogar dumm wäre, perfekt zu sein, dann gäbe es doch nichts mehr zu lernen: über Fahrzeuge, darüber, dass meine Kleine auch als ziemlich grotesker Frosch Spaß an Fasching hat, und dass sie nicht weniger Mama zu mir sagt. nur weil ich krank bin.",
