        "passage": "Einerseits sind die Bedingungen für ein Fernstudium heute natürlich weitaus besser als in den Anfangszeiten. Andererseits aber findet man, wie überall in der digitalen Welt, Zusammenhalt und Nähe nur in einer reduzierten technisch unterkühlten Form. Vieles fehlt, was zumindest für mich immer den Reiz des Studentenlebens ausgemacht hat: Gern denke ich zurück an tiefgründige Gespräche in der Cafeteria und legendäre Studentenpartys, die heute noch Stoff für zahlreiche Erinnerungen bieten. Es war eine Bereicherung mit Kommilitonen und Kommilitonen die köpfe über schwierigen Aufgaben zusammenzustecken oder stundenlang zu diskutieren – in personal freilich, am besten bei einem Abendessen im Studentenwohnheim. Diese Zeit hat mich geprägt, in dieser Zeit habe ich Freunde fürs Leben gewonnen. Online-Kontakte können all dies niemals ersetzen, davon bin ich fest überzeugt.",
