        "german": "Auch die Berufstätigen bezahlen ihr Fernstudium und den Erfolg, den sie sich da Einsamkeit: Denn ohne den Rückzug in die Einsamkeit und Stille lässt sich ein solche bewältigen, auch wenn man online mit vielen andern verbunden sein kann.",
