        "passage": "Auch die Berufstätigen bezahlen ihr Fernstudium und den Erfolg, den sie sich da Einsamkeit: Denn ohne den Rückzug in die Einsamkeit und Stille lässt sich ein solche bewältigen, auch wenn man online mit vielen andern verbunden sein kann. Sozial Zeitaktivitäten stehen in dieser Zeit nicht an erster Stelle darüber sollte man die Doppelbelastung vor Beruf und Studium besteht sogar die Gefahr, dass eine Familienleben schaden nehmen oder gar daran zerbrechen könnte: Ein Fernstudium doch egal, ob berufsbegleitendes oder hauptberufliches Fernstudium, am Ende auf der heimischen Couch den Master machen will, braucht auch heute noch die dest ein wenig mit der Lebensweise eines einsamen Gelehrten anzufreunden.",
