        "text": "Pünktlichkeit ist eine Tugend, der ein ähnliches Schicksal beschieden ist wie den Dinosaurier: Sie ist vom Aussterben bedroht.",
        "german": "Pünktlichkeit ist eine Tugend, der ein ähnliches Schicksal beschieden ist wie den Dinosaurier: Sie ist vom Aussterben bedroht.",
        "firstSentence": "Pünktlichkeit ist eine Tugend, der ein ähnliches Schicksal beschieden ist wie den Dinosaurier: Sie ist vom Aussterben bedroht.",
        "chinese": "守时这项美德像恐龙一样：濒临灭绝。许多人如今把守时视为迂腐、顽固、老派，甚至是对自由 的不必要限制。可说句实话，你自己如何呢？你喜欢等人吗？就算你偶尔也会放任自己迟到，但 当你像“预约好了却没人来”那样在街角干等、或在餐馆被端上第三杯开胃酒时招来侍者的同情目 光，你也会紧张吧。反正我会在这种情形下炸掉：先是气炸，然后因为郁闷而把巧克力或蛋糕塞 太多，或者靠高糖高热量饮料把这段等待咽下去。",
        "sentenceZh": "守时这项美德像恐龙一样：濒临灭绝。",
        "summary": "守时这项美德像恐龙一样：濒临灭绝。",
        "passage": "Pünktlichkeit ist eine Tugend, der ein ähnliches Schicksal beschieden ist wie den Dinosaurier: Sie ist vom Aussterben bedroht. Vielen gilt Pünktlichkeit heute als Zeichen für Pedanterie und Verbohrtheit, als altmodisch, als unnötige Einschränkung der eigenen Freiheit. Aber ganz ehrlich, wie sieht es denn bei Ihnen aus? Warten Sie etwa gerne? Auch wer selbst ab und zu mal fünfe gerade sein lässt, wird doch nervös, wenn er wie bestellt und nicht abgeholt an irgendeiner Straßenecke herumlungert oder im Restaurant vom Kellner, der bereits den dritten Aperitif bringt, mitleidige Blicke erntet. Ich jedenfalls könnte in solchen Situationen platzen: zuerst vor Wut und dann, weil ich vor lauter Frust wieder zu viel Schokolade oder Kuchen in mich hineingestopft habe. Oder den Ärger mit zucker- und sehr kalorienhaltigen Getränken heruntergespült habe, um die Wartezeit zu überbrücken.",
