        "text": "Ich selbst gehöre ja zu den Überpünktlichen.",
        "german": "Ich selbst gehöre ja zu den Überpünktlichen.",
        "firstSentence": "Ich selbst gehöre ja zu den Überpünktlichen.",
        "chinese": "我属于“超守时”的人。宁愿早到五分钟，也不愿匆忙或迟到。我会在约时间前先查公交时刻或导 航路线。凭多年经验，我知道要给不同朋友加上等待时间。有人觉得我这样计划得太细是古怪甚 至控制欲强。但我允许自己这样做，因为我的“经验数据”能帮我调适等待、减轻紧张。我就是缺 乏等待所需的从容——毕竟没人是完美的。而且等待时必须保持从容：否则有心情变坏、发火过 猛、被人当作爱抱怨的刻薄鬼的风险。",
        "sentenceZh": "我属于“超守时”的人。",
        "summary": "我属于“超守时”的人。",
        "passage": "Ich selbst gehöre ja zu den Überpünktlichen. Ich bin lieber fünf Minuten eher da, als gehetzt oder zu spätz kommen. Ich schaue mir die Fahrpläne der öffentlichen Verkehrsmittel an oder die Wege im Navi, bevor ich Termine vereinbare, Durch jahrelange Erfahrung habe ich gelernt, wie viel Wartezeit ich bei den jeweilige Freunden hinzuaddieren muss, Sicher, auf manche wirkt es gewiss schrullig oder gar kontrollsüchtig, auf ich alles so genau plane. Doch ich gestehe mir das zu, denn mir helfen meine empirischen Daten, mich auf das Warten einzustellen - was meine Nervosität lindert. Mir fehlt einfach die Gelassenheit, die man zum Warten braucht- niemand ist schließlich perfekt. Und gelassen sollte man unbedingt bleiben, wenn man warten muss: Sonst besteht die Gefahr, dass es einem die Laune verdirbt, man seinem Arger allzu deutlich Luft macht und man als Griesgram in Verruf gerät.",
