        "summary": "支撑论证？",
        "passage": "Die Gründe dafür sind klar: Das Wissen ändert sich auf vielen Gebieten so schnell wie nie zuvor, es wird kleinteiliger und diverser -teilweise mit sehr kurzen Innovationszyklen. Die heute heiß gehandelte App kann morgen der neue App-Store-Hüter sein. Es ist eine Lebensaufgabe, dabei nicht den Anschluss zu verlieren. Während man früher oft davon ausging, nach der Ausbildung oder dem Studium genug Fertigkeiten für das ganze Berufsleben erworben zu haben, endet die Lernkurve mittlerweile erst mit dem Renteneintritt und so mancher alte Hase drückt wieder die Schulbank. Doch was kann man nun gegen dieses leichte Unbehagen tun, das man manchmal empfindet, wenn man von Jüngeren lernen soll? Muss man vielleicht einfach akzeptieren, dass die klassischen Rollenmuster des Lernens heute passé sind?",
