        "text": "Kevin Weyer jedenfalls hat das verinnerlicht.",
        "german": "Kevin Weyer jedenfalls hat das verinnerlicht.",
        "firstSentence": "Kevin Weyer jedenfalls hat das verinnerlicht.",
        "chinese": "凯文·韦耶显然已将这一理念内化于心。这位现年31岁的记者自25岁起便开始执教。大学毕业一年 后，他就开设了第一门研讨课；如今，他甚至还在教50多岁和60多岁的人如何设计应用程序。一 方面，他教授的课程内容让人很难想象由年长的讲师来授课：在他刚开始教学时，数字新闻和社 交媒体还是未开发的新领域，仿佛专为“数字原住民”量身打造。所谓“数字原住民”，指的是在数 字世界中成长起来、几乎能凭直觉掌握数字世界的人。另一方面，我们完全有理由质疑：缺乏的 教学经验和生活阅历是否能如此轻易地被弥补。毕竟，要成功传授知识，需要的不仅仅是当下特 别抢手的专业知识，更需要社交能力，以及尽可能稳健的性格。不过，如果仅将这些能力归因于 年长者，则应持谨慎态度：人们往往很容易产生偏见，即使自己并不总是意识到这一点。毕竟， 谁能断言年轻讲师就不可能具备所有这些能力呢？又谁能断言年龄增长就必然带来智慧呢？",
        "sentenceZh": "凯文·韦耶显然已将这一理念内化于心。",
        "summary": "凯文·韦耶显然已将这一理念内化于心。",
        "passage": "Kevin Weyer jedenfalls hat das verinnerlicht. Der heute 31-jährige Journalist lehrt schon, seit er 25 war. Ein Jahr nach Abschluss des Studiums gab er sein erstes Seminar, heute bringt er auch 50- und 60- Jährigen bei, wie man eine App entwirft. Einerseits unterrichtet er Themen, bei denen man sich ältere Dozenten nur schwerlich vorstellen kann: Als er begann, waren digitaler Journalismus und Social Media noch Neuland, wie geschaffen für Digital Natives. Damit sind Personen gemeint, die in der digitalen Welt aufgewachsen sind und sich den Zugang dazu nahezu intuitiv erschließen. Andererseits darf man sich durchaus die Frage stellen, ob sich fehlende Lehr- und auch Lebenserfahrung so leicht ersetzen lässt. Denn um erfolgreich Wissen zu vermitteln, braucht man schließlich mehr als die gerade besonders gefragten Spezialkenntnisse, nämlich soziale Kompetenzen und möglichst auch eine gefestigte Persönlichkeit. Man sollte allerdings vorsichtig sein, wenn man solche Fähigkeiten nur Älteren zuschreibt: Allzu leicht neigt man zu Vorurteilen, auch wenn man sich dessen nicht immer bewusst ist. Denn wer sagt eigentlich, dass junge Dozenten nicht über all diese Kompetenzen verfügen können? Und dass Alter automatisch weise macht?",
