        "german": "Weyers Schüler scheinen jedenfalls keine Probleme damit zu haben, sich von einem Dozenten anleiten zu lassen, der teilweise nur halb so alt ist wie sie selbst.",
        "firstSentence": "Weyers Schüler scheinen jedenfalls keine Probleme damit zu haben, sich von einem Dozenten anleiten zu lassen, der teilweise nur halb so alt ist wie sie selbst.",
        "chinese": "作者是否通过诉诸权威来支撑论证？ 无论如何，韦耶斯的学生们似乎并不介意接受一位年龄有时仅为他们一半的讲师的指导。59岁的 莫妮卡·莱尔哈默是其课程中年龄最大的学员。“年轻人往往比年长者更容易掌握技术操作。我们 可以向他们学习很多东西，”这位自由撰稿人说道。继续教育对她而言之所以重要，主要是为了不 被时代淘汰。不过，如今就连40岁的人也已有这种想法。在当今职场中，压力很大：终身学习也 可能带来压力，维尔茨堡大学的教育研究者安德烈亚斯·多尔平豪斯也指出了这一点：“ “那种被抛 在后面、过时、不符合市场需求的不停的恐惧，根本就是终身学习的一部分。”由此可以得出结 论：虽然年长者向年轻人学习可能仍是一种不寻常的教学情境，但在特别前沿的话题上，那些紧 跟时代脉搏的人往往了解得最透彻——也就是年轻人。",
        "sentenceZh": "作者是否通过诉诸权威来支撑论证？",
        "summary": "作者是否通过诉诸权威来支撑论证？",
        "passage": "Weyers Schüler scheinen jedenfalls keine Probleme damit zu haben, sich von einem Dozenten anleiten zu lassen, der teilweise nur halb so alt ist wie sie selbst. Monika Leerhammer ist mit 59 Jahren die Älteste in einem seiner Kurse. Den Jüngeren fällt der Umgang mit technischen Dingen doch oft viel leichter als den Älteren. Von denen kann man sich einiges abschauen\", sagt die freiberufliche Journalistin. Weiterbildung sei ihr vor allem deshalb wichtig, damit sie nicht den Anschluss verliere. Solche Gedanken kennen heute allerdings schon 40-Jährige. In der heutigen Arbeitswelt ist der Druck groß: Lebenslanges Lernen kann auch Stress bedeuten, darauf weist auch der Bildungsforscher Andreas Dörpinghaus von der Universität Würzburg hin:, Die beständige Angst, abgehängt zu werden, zu veralten, nicht marktkonform zu sein, gehört zum lebenslangen Lernen schlichtweg dazu.\" Folgern kann man aus alldem also: Es mag noch immer eine ungewohnte Unterrichtssituation sein, wenn die Älteren von den Jüngeren lernen. Doch über besonders aktuelle Themen wissen oft diejenigen am besten Bescheid, die am Puls der Zeit sind: die Jüngeren also →",
