        "text": "Mondwissen sei uraltes Wissen unserer Ahnen, argumentieren hingegen jene, die vom Einfluss des Mondes auf unser Dasein überzeugt sind.",
        "german": "Mondwissen sei uraltes Wissen unserer Ahnen, argumentieren hingegen jene, die vom Einfluss des Mondes auf unser Dasein überzeugt sind.",
        "firstSentence": "Mondwissen sei uraltes Wissen unserer Ahnen, argumentieren hingegen jene, die vom Einfluss des Mondes auf unser Dasein überzeugt sind.",
        "chinese": "证”？ 与之相反，那些坚信月亮影响我们存在的人争辩说：“月亮知识”是祖先的远古智慧。很多人对先人自以为掌 握的“自然节律知识”不加质疑，他们对月历发誓效忠。所谓**“月历”，就是把一年月相精确列出的日历— 其中凝结着代代农民观察田间生长周期的知识。对这种论证，本文作者也并非完全不能接受。但民俗学家 Helmut Groschwitz 持不同意见：他在“月亮信仰”中几乎找不到**“传统久远”的东西；他在中世纪晚期的 文献才见到月历踪迹，而这些并非出自农民，而是医生写的：他们给出放血及其他医疗操作的合适时机建议。 但这些文献并不普及。直到浪漫主义时期月亮规则才再度出现，并在 20 世纪初再度更广泛传播。",
        "sentenceZh": "证”？",
        "summary": "证”？",
        "passage": "Mondwissen sei uraltes Wissen unserer Ahnen, argumentieren hingegen jene, die vom Einfluss des Mondes auf unser Dasein überzeugt sind. Und was die Ahnen über den Rhythmus der Natur zu wissen glaubten, wird von vielen nicht in Frage gestellt. Diese schwören auf Mondkalender. Das sind Kalender, in denen die Mondphasen eines Jahres genau aufgelistet sind. In ihnen steckt schließlich das gesammelte Wissen von Generationen von Bauern, die den Wachstumszyklus auf den Feldern beobachteten. Diesem Argument kann auch der Autor dieser Zeilen etwas abgewinnen. Der Volkskundler Helmut Groschwitz ist anderer Meinung. Er fand im Mondglauben wenig Althergebrachtes. Auf die ersten Spuren von Mondkalendern ist er in spätmittelalterlichen Schriften gestoßen. Sie stammen aber nicht von Bauern, sondern von Ärzten. Diese gaben Ratschläge zum geeigneten Zeitpunkt, Blut abzuzapfen und andere medizinische Untersuchungen durchzuführen. Weitverbreitet waren diese Schriften aber nicht. Erst in der Romantik tauchen Mondregeln erneut auf und verbreiten sich Anfang des 20. Jahrhunderts wieder stärker.",
