        "firstSentence": "So skeptisch Wissenschaftler das Phänomen der Mondglaubigkeit auch sehen mögen - das Interesse an dem Himmelskörper ist nach wie vor sehr groß.",
        "chinese": "尽管科学家们对“月球信仰”这一现象持怀疑态度，但人们对这颗天体的兴趣依然十分浓厚。仍有 许多悬而未决的问题值得进一步探讨：如果月球不存在，会怎样？月亮对地球上生命起源的影响 究竟有多大？如果没有由月亮决定的潮汐，生命能否从水中登陆？植物、动物和人类能否进化而 来？如果月亮不对其进行制动，地球的自转速度会更快吗？如果自转速度更快，植物和人类的体 型会更小吗？最后：如果没有月亮，我们还会存在吗？",
        "sentenceZh": "尽管科学家们对“月球信仰”这一现象持怀疑态度，但人们对这颗天体的兴趣依然十分浓厚。",
        "summary": "尽管科学家们对“月球信仰”这一现象持怀疑态度，但人们对这颗天体的兴趣依然十分浓厚。",
        "passage": "So skeptisch Wissenschaftler das Phänomen der Mondglaubigkeit auch sehen mögen - das Interesse an dem Himmelskörper ist nach wie vor sehr groß. Es gibt noch zahlreiche offene Fragen, die man weiterverfolgen sollte: Was wäre, wenn es den Mond nicht gäbe? Wie groß war wohl der Einfluss des Mondes auf die Entstehung des Lebens auf der Erde? Wäre ohne die Gezeiten, die vom Mond bestimmt werden, das Leben aus dem Wasser aufs Land gekommen? Wären Pflanzen, Tiere und Menschen entstanden? Würde die Erde sich schneller drehen, wenn der Mond sie nicht bremsen würde? Wären bei stärkerer Umdrehung die Pflanzen, die Menschen kleiner? Und schließlich: Gäbe es uns überhaupt ohne den Mond?",
