        "firstSentence": "Mach es selbst!",
        "chinese": "动手做吧！那句著名口号 do it yourself 如今正当其时。从蛋杯到布餐巾，一切都得个性化。鼠标垫、门垫、 自行车座套被刷画、编织、缝制——至于往往存疑的成品效果反倒成了其次。甚至连路灯杆，如今也要穿上一 件针织“衣服”来体现个性。手作据说能爱护地球、抑制大众消费，针织圈的活动家们为此欢呼。而紧跟潮流 的人，会自己做酸菜。这据不少美食博客宣称“一点也不难，特别有趣、味道更好”。当然得花点钱——要买 合适的密封罐，最好再来个切菜器，去上上课程、买买相关书……看起来无论如何都得安排不少时间。各位读 者，您是否同意：在这种情况下，这股热情是不是有点过了？多年来，“自己动手”一直是潮流，而同样多年， 人们也一直得问：为什么有人愿意自学成“半吊子”、投入巨大精力去做那些明明可以完美现成买到的东西？ 比如罐装酸菜——每家超市都有。",
        "sentenceZh": "动手做吧！",
        "summary": "动手做吧！",
        "passage": "Mach es selbst! Die bekannte Parole do it yourself hat heute Hochkonjunktur. Vom Eierwärmer bis zur Stoffserviette muss alles individuell gestaltet sein. Mousepads, Türvorleger, Fahrradsitzbezüge werden bepinselt, geklöppelt und genäht - dasoft fragwürdige Ergebnis ist dabei zweitrangig. Sogar Laternenstangen wird heutzutage Individualität miteinem Strickkleid verpasst. Selber machen schone den Planeten und dämme den Massenkonsum ein, jubeln Aktivistenaus Stricknadel kreisen. Und wer sich auf der Höheder Zeit bewegt, produziert sein Sauerkraut selbst. Das sei überhaupt nicht schwer, mache jede MengeSpaß und schmecke einfach viel besser, versprechenetliche Kochblogs. Ein bisschen Geld müsse man dafür natürlich aufwenden, die passenden Einmachgläser solle man kaufen, ein Gemüsehobelkönne nicht schaden, auch Kurse und entsprechende Literatur würden sich lohnen ... Es scheint jedenfalls, als müsste man dafür viel Zeit einplanen. Würden Sie, liebe Leser, sich der Meinung anschließen, dass in diesem Fall die Begeisterung doch ein wenig übertrieben ist? Schon seit Jahren liegt Selbermachenim Trend, und ebenso lange muss man sich fragen, warum Leute freiwillig, dilettantisch und unter hohem Aufwand Dinge herstellen, die sie perfekt und gebrauchsfertig kaufen könnten. Wie etwa Sauerkraut aus der Dose - das findet man schließlich in jedem Lebensmittelgeschäft.",
