        "chinese": "是的，我承认：我很容易满足。我喜欢超市里的现成品；要给家里重新装饰，我不会开动手工，而是去某个知 名瑞典家具商逛一圈。尽管如此，别人乐在手作，我完全不反对；对这股潮流我也能看到积极的一面。亲手做 点什么，的确有助于放松，让人在劳累的一天后清空头脑。而投入到手作里，至少不会把时间浪费在无目的地 网上乱逛上。另一方面，当下把手作拔得过高、几乎当作“拯救世界”，这点让我非常反感。",
        "sentenceZh": "是的，我承认：我很容易满足。",
