        "text": "Das Heimwerken solle das GIücksempfinden erhöhen, die zwischen Mensch und Arbeit überwinden, dem Klima guttun und den Konsum eindämmen: Solche Behauptungen hört man immer wieder.",
        "german": "Das Heimwerken solle das GIücksempfinden erhöhen, die zwischen Mensch und Arbeit überwinden, dem Klima guttun und den Konsum eindämmen: Solche Behauptungen hört man immer wieder.",
        "firstSentence": "Das Heimwerken solle das GIücksempfinden erhöhen, die zwischen Mensch und Arbeit überwinden, dem Klima guttun und den Konsum eindämmen: Solche Behauptungen hört man immer wieder.",
        "chinese": "人们常常听到这样的主张：家居手作能提升幸福感、弥合人与工作的隔阂、有益气候并减少消费。对抱有如此 高期待的人，真想回一句：该踩一脚刹车了！ 这个话题真的该更冷静些看待。举个例子：“手作减少消费”未 必成立。 光看相关商家的销售额就说明——手作与购买如同锤子与钉子般相依：为自制某物，你要先买需要的 工具与材料。这既不减少消耗，也不降低成本。并且行业早已嗅到趋势，提供大量“半成品”。所以完全可以 说：由于人们热爱手作，消费非但没有减少，反倒被带动起来。",
        "sentenceZh": "人们常常听到这样的主张：家居手作能提升幸福感、弥合人与工作的隔阂、有益气候并减少消费。",
        "summary": "人们常常听到这样的主张：家居手作能提升幸福感、弥合人与工作的隔阂、有益气候并减少消费。",
        "passage": "Das Heimwerken solle das GIücksempfinden erhöhen, die zwischen Mensch und Arbeit überwinden, dem Klima guttun und den Konsum eindämmen: Solche Behauptungen hört man immer wieder. Den jenigen, die so hohe Erwartungen haben, möchte man entgegenrufen: Schaltet mal einen Gang herunter! Man sollte dieses Thema wirklich etwas nüchterner betrachten. Ein Beispiel: Dass Selberm achen den Konsum reduziert, ist durchaus fraglich. Allein die Umsatzzahlen der entsprechenden Geschäfte belegen, dass Heimwerken und Kaufen zusammengehören wie Hammer und Nagel. Schließlich wird Geld ausgegeben für Dinge, die man braucht, um andere Dinge selbst zu produzieren. Dies reauziert weder Verbrauch noch Kosten. Und die Industrie hat den Trend natürlich schon lange erkannt und bietet zahlreiche Produkte in halbfertigem Zustand an. Man könnte also durchaus behaupten. dass der Konsum durch die Liebe zum Heimwerken nicht reduzien, sondern sogar angekurbelt wird.",
