        "chinese": "为何手作在沉寂多时后又成了潮流？可以确定的是：在工作中日日对着电脑、频繁浸泡于互联网与社交媒体视 觉世界的人，终究渴望一种“平衡”。渴望一个对立面：用自己的手创造点什么、证明自己的能力；闻到油漆、 触摸木头、以感官去体验事物。一天结束时，手里能捧着成果，拿给别人看。按神经生物学家Gerald Hüther 的一个论断：很多人在工作中已经感受不到自己行为的重要性，在那里几乎无法施加影响；但在家里，他们说 了算。",
