        "chinese": "但并非总是个人想象力就够用，有时确实需要榜样。而这些榜样偏偏就出现在社交网络里。这听上去或许自相 矛盾：恰恰是人们想从这些虚拟世界中抽身。然而——无论你想缝点什么、还是做张新床——线上到处都是现 成教程，还能轻松汲取众人的经验。交流还会催生社群/共同体。因此完全可以认为：人们借此更贴近，也满足 了对共同性的需求——这正是爱好所能起到的作用。为朋友们亲手织的毛衣和自制书架骄傲地晒图、互相欣赏， 也许只是众多“与别人相遇”的方式之一。最终很可能并不在于自制酸菜是否更好吃，而在于你能与别人聊起 它。",
        "sentenceZh": "但并非总是个人想象力就够用，有时确实需要榜样。",
        "summary": "但并非总是个人想象力就够用，有时确实需要榜样。",
        "passage": "Nicht immer reicht aber die eigene Fantasie aus, manchmal braucht man eben doch Vorbilder. Und diese finden sich ausgerechnet in den sozialen Netzwerken. Das mag zunächst wie ein Widerspruch klingen, denn gerade von diesen virtuellen Welten wunschen sich doch viele eine Auszeit. Dennoch: Ob sie etwas nähen oder ein neues Bett bauen wollen - online finden Bastler zu jedem Thema eine passende Anleitung, und man kann leicht den Erfahrungsschatz vieler Leute anzapfen. Durch den Austausch entstehen außerdem Communitys, Gemeinschaften. Man könnte also durchaus annehmen, dass die Menschen sich auf diese Weise näherkommen und ihr Bedürfnis nach Gemeinsamkeit ausleben können auch dazu dienen schließlich Hobbys. Wenn man stolz Fotos selbstgestrickten Pullis und die selbstgebauten Regale von Freunden bewundert, ist dies vielleicht nur eine von vielen Möglichkeiten, anderen zu begegnen. Letztlich kommt es womöglich gar nicht darauf an, dass selbstgemachtes Sauerkraut besser schmeckt. Sondern darauf, dass man mit anderen darüber reden kann.",
        "frage": "spricht die Autorin eine Vermutung aus?",
        "answer": "",
