        "text": "Eines der schönsten Wörter der deutschen Sprache lautet: Erfahrung.",
        "german": "Eines der schönsten Wörter der deutschen Sprache lautet: Erfahrung.",
        "firstSentence": "Eines der schönsten Wörter der deutschen Sprache lautet: Erfahrung.",
        "chinese": "一个术语定义？ 德语里最美的词之一是“Erfahrung（经验）”。它表明：知识、世故与开阔的眼界，特别是通过行走 在路上获得。总呆在一个地方，得不到新东西，也是在限制自己。旅行所得的印象，比日 常的家常体验更深地刻进记忆。我永远忘不了第一次坐飞机、第一次和父母看到大海的那一刻。直到今 天，我还眼睛发亮地讲起高中毕业后那三个月的欧洲背包游。我由衷相信，渴望在路上写在我们的DNA 里。来自他乡的产品、思想与词语，我们乐于拿来并加以利用。世界不断来到我们这里，我们也不断去 到世界。",
        "sentenceZh": "一个术语定义？",
        "summary": "一个术语定义？",
        "passage": "Eines der schönsten Wörter der deutschen Sprache lautet: Erfahrung. Es besagt, dass Wissen, Weltgewandtheit und ein weiter Horizont besonders durch das Fahren, durch das Unterwegs-Sein erworben werden. Wer immer nur an einem Ort verharrt, bekommt nichts Neues mit und beschränkt sich dadurch selbst. Denn die Eindrücke, die man auf Reisen erwirbt, schreiben sich viel tiefer in die Erinnerung ein als die üblichen Alltagserfahrungen zuhause. Nie werde ich den Moment vergessen, als ich zum ersten Mal in ein Flugzeug stieg, mit meinen Eltern zum ersten Mal am Meer war. Und noch heute erzähle ich mit leuchtenden Augen von der dreimonatigen Rucksackreise durch Europa, die ich nach dem Abitur unternommen habe. Ich bin zutiefst davon überzeugt, dass uns der Wunsch, unterwegs zu sein, in die DANN geschrieben ist. Produkte, Ideen und Wörter, die aus anderen Gegenden als unserer Heimat stammen, nehmen wir uns gerne zu eigen und nutzen ihre Vorteile. So reist die Welt beständig zu uns, und wir reisen in die Welt.",
