        "text": "Reisen ist kein Luxus, sondern eine Notwendigkeit.",
        "german": "Reisen ist kein Luxus, sondern eine Notwendigkeit.",
        "firstSentence": "Reisen ist kein Luxus, sondern eine Notwendigkeit.",
        "chinese": "旅行不是奢侈，而是必要。旅游业正在繁荣，但早在定居之前人类就一直在路上：先是出于迫不得已， 再是出于好奇，最后纯粹为发现的乐趣。富裕者若负担得起，就会出发去探索世界之美、开阔眼界。早 在古代，富有的罗马人就去那不勒斯湾或亚得里亚海旅行。令人奇怪的是，即使在中世纪生活极其艰难， 人们也没有呆在家里；即使在战争或瘟疫时期，仍有数十万人走在欧洲各地的朝圣路上。后来，近代的 富有贵族给儿子“规定”文化教育旅行：要在社会上立足、在晚宴上拿出许多轶事，巴黎、威尼斯、佛 罗伦萨、那不勒斯、罗马，甚至维也纳、阿姆斯特丹都得亲眼见识过。",
        "sentenceZh": "旅行不是奢侈，而是必要。",
        "summary": "旅行不是奢侈，而是必要。",
        "passage": "Reisen ist kein Luxus, sondern eine Notwendigkeit. Der Tourismus boomt, doch schon lange vor der Sesshaftwerdung waren Menschen unterwegs, erst aus Not, dann aus Neugier und schließlich aus reiner Lust am Entdecken. Wer es sich leisten konnte, machte sich auf, um die Schönheit der Welt zu erkunden und über den Tellerrand zu schauen. Bereits in der Antike reisten wohlhabende Römer an den Golf von Neapel oder an die Adria. Verwunderlich ist, dass selbst im Mittelalter, als die Lebensumstände ausgesprochen beschwerlich waren, die Menschen nicht zu Hause blieben. Auch in Zeiten von Kriegen oder Seuchen reisten Hunderttausende auf Pilgerpfaden quer durch Europa. Später verordneten wohlhabende Adelige der Neuzeit ihren Söhnen Bildungsreisen zu Schlüsselorten unserer Kultur. Paris und Venedig, Florenz, Neapel und Rom, aber auch Wien und Amsterdam musste man gesehen haben, um in der Gesellschaft bestehen und durch zahlreiche Anekdoten zur Abendunterhaltung beitragen zu können.",
