        "number": "5",
        "paragraph": "E",
        "text": "Wie dem auch sei.",
        "german": "Wie dem auch sei.",
        "firstSentence": "Wie dem auch sei.",
        "chinese": "无论如何，我们的时代有一个好处：我们有机会通过旅行走进别样文化、学习新知——无论你喜欢沙滩 躺椅还是美术馆/教堂的艺术游。想想看：如果人们从未尝试探索新地方、从未把所见所获据为己用，我 们的生活会怎样？这不也相当凄清吗？如果我们不一次次在路上，我们会多么无知。当然，家里也可以 很惬意。但“旅行让人更快乐”，科学研究也这么说——比如芬兰坦佩雷大学前些时候的一项研究：它 得出的结论是，度假比在家休息一天更能恢复，因为度假没有日常义务且获得新印象。所以，在路上确 实会让人更快乐。",
        "sentenceZh": "无论如何，我们的时代有一个好处：我们有机会通过旅行走进别样文化、学习新知——无论你喜欢沙滩 躺椅还是美术馆/教堂的艺术游。",
        "summary": "无论如何，我们的时代有一个好处：我们有机会通过旅行走进别样文化、学习新知——无论你喜欢沙滩 躺椅还是美术馆/教堂的艺术游。",
        "passage": "Wie dem auch sei. Es gehört zu den Vorzügen unserer Zeit, dass wir die Möglichkeit haben, durch Reisen in andere Kulturen einzutauchen und Neues zu lernen, egal ob man die Ferien lieber im Liegestuhl am Strand oder mit dem Kunstreiseführer in Museen und Kathedralen verbringt. Überlegen Sie sich doch einmal, wie unser Leben wäre, wenn die Menschen nie versucht hätten, neue Gegenden zu erkunden und die Errungenschaften, die ihnen dort begegneten, für sich zu entdecken. Erscheint Ihnen diese Vorstellung nicht auch ziemlich trostlos? Wie wenig wüssten wir über die Welt, in der wir leben, wenn wir nicht immer wieder unterwegs wären.Ohne Zweifel kann es daheim gemütlich sein. Doch dass Reisen glücklich macht, das besagen auch wissenschaftliche Studien, wie zum Beispiel jene, die vor einiger Zeit von der Universität Tampere in Finnland durchgeführt wurde. Sie kam zu dem Ergebnis, dass wir uns im Urlaub besser erholen als an einem freien Tag zu Hause. Denn im Urlaub sind wir gänzlich frei von alltäglichen Verpflichtungen und gewinnen neue Eindrücke. Unterwegs zu sein macht also wirklich glücklich.",
