        "text": "Kürzlich hat ein Meinungsforschungsinstitut eine repräsentative Umfrage veröffentlicht.",
        "german": "Kürzlich hat ein Meinungsforschungsinstitut eine repräsentative Umfrage veröffentlicht.",
        "firstSentence": "Kürzlich hat ein Meinungsforschungsinstitut eine repräsentative Umfrage veröffentlicht.",
        "chinese": "一家民调机构发布了代表性调查：越来越多人独自去餐馆；但三分之一的受访者仍无法想象独自用餐。 更有意思的不是数字，而是解读：记者们几乎“苦思冥想”地猜测独自用餐者的成因——有的说“为了 在人群中待着”，有的反说“为躲清净/家里太累/懒得做饭”，还有人说“单身户增加/孤独问题严峻”， 并贴心给“怎样搭话”的建议。作者讥讽：难道那个“孤零零扒饭的怪人”会想不到从聊天气开始吗？",
        "sentenceZh": "一家民调机构发布了代表性调查：越来越多人独自去餐馆；但三分之一的受访者仍无法想象独自用餐。",
        "summary": "一家民调机构发布了代表性调查：越来越多人独自去餐馆；但三分之一的受访者仍无法想象独自用餐。",
        "passage": "Kürzlich hat ein Meinungsforschungsinstitut eine repräsentative Umfrage veröffentlicht. Das Ergebnis: Immer mehr Menschen gehen allein ins Restaurant oder in die Gaststätte. Für ein Drittel der Befragten bleibt das Solodinner aber weiterhin unvorstellbar: Sie sind noch nie allein in einem Restaurant gewesen. Interessant an der Studie sind aber weniger die Zahlen, sondern vielmehr ihre Deutung: So versuchen Journalisten, die sich mit dieser Studie auseinandersetzen, beinahe schon verzweifelt, die unbekannte Spezies der Alleinesser zu ergründen. „Es sind viele Gründe vorstellbar, warum Menschen in ihrer Freizeit allein ins Restaurant gehen“, schreibt einer. Zum Beispiel, um unter Leuten zu sein.“ Ein anderer äußert die gegenteilige Vermutung: „Um für zwei Stunden seine Ruhe zu haben, weil es zuhause mit der Familie zu stressig ist. Oder weil man schlicht zu faul zum Kochen ist.“ Und es gibt noch weitere Theorien: „Es gibt immer mehr Singlehaushalte und auch ein großes Problem mit Einsamkeit“, schreibt ein anderer Journalist. Voller Mitleid mit den armen Menschen, die niemanden haben, der mit ihnen zu Abend isst, fügt er gutgemeinte Tipps hinzu, wie man in Kneipen schnell ins Gespräch kommt. Man könne zum Beispiel zum Einstieg über das Wetter reden, heißt es da. Nun, darauf ist dieser einsame komische Kauz, der allein sein Essen in sich hineinschaufelt, sicher noch nie gekommen.",
