        "text": "Was in den Texten zu dem Thema nicht mal am Rande erwähnt wird, Es gibt auch Menschen, die aus voller Überzeugung und ganz bewusst allein ins Restaurant geht und Es gibticht, wed sie es mussten oder dort zwingend Kontakt suchten.",
        "german": "Was in den Texten zu dem Thema nicht mal am Rande erwähnt wird, Es gibt auch Menschen, die aus voller Überzeugung und ganz bewusst allein ins Restaurant geht und Es gibticht, wed sie es mussten oder dort zwingend Kontakt suchten.",
        "firstSentence": "Was in den Texten zu dem Thema nicht mal am Rande erwähnt wird, Es gibt auch Menschen, die aus voller Überzeugung und ganz bewusst allein ins Restaurant geht und Es gibticht, wed sie es mussten oder dort zwingend Kontakt suchten.",
        "chinese": "关于这个话题的文字中甚至连字里行间都没提到：也有人出于坚定的信念，有意识地独自去餐厅用餐，这并非 因为他们不得不去，也不是为了在那里刻意寻求社交。而是因为独处虽然并非他们生活的一部分，但这甚至与 孤独感无关。是的，这种观点乍听之下或许有些值得商榷。因为事实上，在我们的社会中，独处几乎是不被接 受的。就连我——本文的作者——也自认为就是其中一个“无趣之人”，一个“独食者”。也许正因为我是个 内向的人，才如此享受独处。我喜欢安静，渴望宁静——并在独处的时间里为自己补充能量。开放式办公室、 会议、喧闹的酒吧、充斥着无聊闲聊的派对——这一切都让我倍感疲惫，以至于我常常需要好几天才能让自己 的“电量”恢复。",
        "sentenceZh": "关于这个话题的文字中甚至连字里行间都没提到：也有人出于坚定的信念，有意识地独自去餐厅用餐，这并非 因为他们不得不去，也不是为了在那里刻意寻求社交。",
        "summary": "关于这个话题的文字中甚至连字里行间都没提到：也有人出于坚定的信念，有意识地独自去餐厅用餐，这并非 因为他们不得不去，也不是为了在那里刻意寻求社交。",
        "passage": "Was in den Texten zu dem Thema nicht mal am Rande erwähnt wird, Es gibt auch Menschen, die aus voller Überzeugung und ganz bewusst allein ins Restaurant geht und Es gibticht, wed sie es mussten oder dort zwingend Kontakt suchten. Sondern weil das Allt geheed zwar ni Bestandteil ihres Lebens ist. Und das hat nicht mal mit Einsamkeit zu tun. Ja, diese Theone mag zunächst einmal fragwürdig klingen. Denn tatsächlich ist das Alleinsein in unserer Gesellschaft kaum akzeptiert. Auch ich, der Autor dieses Textes, verstehe mich als einer dieser Langweiler, als einer dieser Alleinesser Vielleicht genieße ich das Alleinsein so sehr, weil ich ein introvertierter Mensch bin. Ich mag es leise, sehne mich nach Ruhe - und tanke in der Zeit, die ich allein verbringe, Energie. Großraumbüros, Meetings, laute Kneipen, Partys mit belanglosem Small Talk - all das strapaziert mich so sehr, dass ich oftmals Tage brauche, um meinen Akku wieder aufzuladen.",
