        "firstSentence": "Dennoch weckt es in ihnen manchmal zwiespältige Gefühle, wenn sie etwa im Restaurant allein sind.",
        "chinese": "尽管如此，当他们独自一人在餐厅时，内心有时仍会产生矛盾的情绪。如果您试着想象自己身处这种情 境，一定能感同身受：您独自坐在餐桌旁，周围尽是成双成对的情侣和一家人，过了一会儿，便会感到某 种不自在。因为尽管你喜欢独处，却总觉得能感受到周围人的目光，这会让你产生自我怀疑。原因在于所 谓的“聚光灯效应”。它指的是那种感觉，仿佛周围所有人都盯着你看。“当我独自坐在这里时，其他客人会 怎么想呢？我看起来是否不友好或冷淡？” 这样的念头几乎会不由自主地闪过脑海。或者，你会担心被误 认为是厌世者，也就是憎恶人类的人。",
        "sentenceZh": "尽管如此，当他们独自一人在餐厅时，内心有时仍会产生矛盾的情绪。",
        "summary": "尽管如此，当他们独自一人在餐厅时，内心有时仍会产生矛盾的情绪。",
        "passage": "Dennoch weckt es in ihnen manchmal zwiespältige Gefühle, wenn sie etwa im Restaurant allein sind. Dies können Sie sicher nachvollziehen, wenn Sie sich vorstellen, wie Sie sich in einer solchen Situation fühlen würden: Sie sitzen allein am Tisch, umgeben von Paaren und Familien, und nach einiger Zeit stellt sich ein gewisses Unwohlsein ein. Denn obwohl Sie gerne allein sind, glauben Sie die Blicke der Umgebung zu spüren, was bei Ihnen Selbstzweifel aufkommen lässt. Grund dafür ist der sogenannte Spotlight-Effekt. Bezeichnet wird damit das Gefühl, dass alle um einen herum einen ansehen würden. Was denken wohl die anderen Gäste wenn ich hier ganz allein sitze Wirke ich unfreundlich oder abweisend? Solche Gedanken schießen einem dann beinahe unwillkürlich durch den Kopf. Oder man hat Angst, für einen Misanthropen, einen Menschenfeind also, gehalten zu werden.",
