        "german": "Die Frage ist nur: Sind es wirklich die eigenen Zweifel?",
        "firstSentence": "Die Frage ist nur: Sind es wirklich die eigenen Zweifel?",
        "chinese": "问题只是：这些真的只是我们自身的怀疑吗？还是说，它们不过是社会自古以来强加给我们的？因为至 少两人结伴去餐厅、共同生活、一起旅行，这些都被视为理所当然？而且，对于许多人来说，一旦偏离 这种标准的生活模式，似乎就难以想象？这个问题或许无法给出最终的答案。不过，更重要的是要转变 思维方式。以下建议无疑很有帮助：社会不应再将那些自觉且自愿独处的人描绘成外星生物。这本身就 是朝着“正常”迈出的一小步。",
