        "german": "Doch wie kann Konsum überhaupt Umweltbewusstsein?",
        "firstSentence": "Doch wie kann Konsum überhaupt Umweltbewusstsein?",
        "chinese": "在哪一段作者用数据与事实论证？ 但消费怎么可能与环保意识相提并论？这本身不就是自相矛盾的吗？众所周知，每次消费都会增加资源消 耗。联合国的一个专家小组指出，那些几乎没怎么用就很快被丢弃的商品，对环境造成的负担甚至远比廉 价航班还要大。以服装为例：自20世纪50年代以来，纺织品的制造、购买和废弃量持续攀升，而其中几乎 没有任何部分被回收利用。纺织品的生产需要大量的水资源，以及用于种植棉花和其他纤维的土地。此 外，时尚行业据称占全球二氧化碳排放量的10%——这一比例甚至超过了国际航空和海运的总和。",
        "sentenceZh": "在哪一段作者用数据与事实论证？",
        "summary": "在哪一段作者用数据与事实论证？",
        "passage": "Doch wie kann Konsum überhaupt Umweltbewusstsein? Ist dies nicht per se ein Widerspruch? Mit jedem Kauf steigt bekanntlich der Ressourcenverbrauch. Eine Expertengruppe der Vereinten Nationen stellte fest, dass kaum genutzte und schnell wieder entsorgte Waren die Umwelt noch weitaus stärker belasten als Billigflieger. Beispiel Kleidung: Seit den 1950er-Jahren stiegen Herstellung, Kauf und Entsorgung von Textilien bergauf, von dem so gut wie nichts recycelt wird. Für die Herstellung von Textilien werden große Mengen Wassers sowie Flächen zum Anbau von Baumwolle und anderen Fasern benötigt. Zudem soll die Modebranche 10 Prozent der weltweiten CO2-Emissionen verursachen – mehr als internationale Luftfahrt und Seeschifffahrt zusammen.",
        "frage": "In welchem Abschnitt argumentiert die Autorin mit Zahlen und Fakten ?",
