        "german": "Käufe – so nachhaltig die Produkte auch sein mögen – der Umwelt in jedem Falle eher schaden als nützen.",
        "firstSentence": "Käufe – so nachhaltig die Produkte auch sein mögen – der Umwelt in jedem Falle eher schaden als nützen.",
        "chinese": "无论这些产品多么环保，购买行为在任何情况下对环境的危害都远大于益处。因此，比起仅仅给购 物狂潮披上一层“绿色”外衣，还有更好的方式来为环保做出贡献。最值得推荐的莫过于减少消费。 因此，对于任何真正重视可持续性的人，我都建议大家修补旧物，而不是购买新物。我们应当重新 拿起补袜针，将其插入破洞的袜子中，将线穿入针眼，然后把大脚趾处的破洞补好。因为除了那个 破洞，袜子的其他部分仍然完好无损。因此，掌握针线活绝对应该成为可持续生活方式的一部分。",
        "sentenceZh": "无论这些产品多么环保，购买行为在任何情况下对环境的危害都远大于益处。",
        "summary": "无论这些产品多么环保，购买行为在任何情况下对环境的危害都远大于益处。",
        "passage": "Käufe – so nachhaltig die Produkte auch sein mögen – der Umwelt in jedem Falle eher schaden als nützen. Es gibt also bessere Wege, einen ökologischen Beitrag zu leisten, als dem Kaufrausch einfach nur einen grünen Anstrich zu verpassen. Empfehlenswert ist es vor allem, den Konsum zu reduzieren. So kann man jedem, der es ernst meint mit der Nachhaltigkeit, ans Herz legen, Sachen auszubessern statt neu anzuschaffen. Es gilt, das Stopfei wieder in die Hand zu nehmen, es in die kaputte Socke zu versenken, das Garn durch die Nadel zu fädeln und das Loch am großen Zeh zu stopfen. Denn rund um das Loch ist die Socke immer noch gut. Der Umgang mit Nadel und Faden sollte daher unbedingt zum nachhaltigen Lebensstil dazugehören.",
