        "chinese": "立场？ 为了避免产生误解：当然，购买环保生产的商品本身并无不妥——前提是这确实有必要。我本人非 常重视公平贸易的服装，拒绝廉价服装，只购买那些即使过几年仍能让我感到愉悦的高品质衣物。 但许多人买新袜子并不需要等旧袜子穿出洞来，这正是问题的症结所在。他们更倾向于认为，通过 用生态纯素大麻羊毛袜取代专业运动领域中那些崭新的高科技合成纤维袜，就能拯救世界。也可能 是用新的竹制牙刷替换塑料牙刷。或者用有机鞋代替那些虽然还好但已经旧了的鞋子。一个锌板制 成的浇水壶，一辆新自行车——因为如今必须是货运自行车，一台能效等级为A+++的新洗衣机，用 来替换那台耗电量多出几瓦的旧洗衣机。",
