        "firstSentence": "Immerhin, bei den Unternehmen ist inzwischen die Erkenntnis angekommen, dass exzessivem Konsum nicht das allerbeste Image anhaftet.",
        "chinese": "话虽如此，企业界如今已意识到，过度消费并不能带来最佳的形象。但这似乎并未引发广泛的观念 转变。这很遗憾，毕竟现在正是我们开始改变消费行为的当务之急。相反，一些制造商甚至利用人 们在进行非必要消费时常有的内疚感来刺激销售。纽约就提供了一个例子：一家销售户外服装的公 司，竟然建议消费者“不要”购买这些衣服。在他们的第一则广告中，该公司精准地道出了整个消费 困境的症结： “别买这件夹克。别买你不需要的东西。”结果如何？在随后的十年里，该公司的销售 额成倍增长。",
