        "passage": "Immerhin, bei den Unternehmen ist inzwischen die Erkenntnis angekommen, dass exzessivem Konsum nicht das allerbeste Image anhaftet. Doch es sieht nicht so aus, als würde dies zu einem breiten Umdenken führen. Das ist schade, schließlich ist es allerhöchste Zeit, dass wir anfangen, unser Konsumverhalten zu ändern. Stattdessen nutzen einige Hersteller sogar das schlechte Gewissen, das überflüssige Käufe oftmals begleitet, um ihr Geschäft anzukurbeln. Ein Beispiel fällt gleich aus New York: Eine Firma, die Outdoor- Kleidung verkauft, riet dazu, diese NICHT zu kaufen. In ihrer allerersten Anzeige brachte Firma das komplette Konsum-Dilemma exakt auf den Punkt: „Kauf diese Jacke nicht. Kauf nicht, was du nicht brauchst.“ Was geschah? In der folgenden Dekade vervielfachten sich ihren Umsatz.",
