        "text": "Man konnte so beginnen: die folgenden Untersuchung handelt von der interaktiven Desintegration Von Rollendtrukturen und Handlungswissen in minimalen Organisation.",
        "german": "Man konnte so beginnen: die folgenden Untersuchung handelt von der interaktiven Desintegration Von Rollendtrukturen und Handlungswissen in minimalen Organisation.",
        "firstSentence": "Man konnte so beginnen: die folgenden Untersuchung handelt von der interaktiven Desintegration Von Rollendtrukturen und Handlungswissen in minimalen Organisation.",
        "chinese": "可以这样开头：下文探讨的是最小组织中角色结构与行动知识的交互式瓦解。不，请稍等！我们 重新开始：那20名足球运动员根本没有机会认真训练。当地酒吧的诱惑实在太大了。下班后的啤 酒喝起来太爽了。但为什么偏偏有两名足球运动员能坚持定期参加训练呢？这样写起来就更好 了。这完全可以作为一部小说的开头。但实际上，这是篇关于组织瓦解的社会学论文的开篇。这 篇论文有两个开头：一个是上面用晦涩的专业术语写成的，另一个则听起来更像好莱坞电影。这 篇论文的精妙之处在于，它将这两个开头融合成一个结局——作为读者，你几乎会为此感到惋 惜，因为这也意味着一场极致智力享受的终结。",
        "sentenceZh": "可以这样开头：下文探讨的是最小组织中角色结构与行动知识的交互式瓦解。",
        "summary": "可以这样开头：下文探讨的是最小组织中角色结构与行动知识的交互式瓦解。",
        "passage": "Man konnte so beginnen: die folgenden Untersuchung handelt von der interaktiven Desintegration Von Rollendtrukturen und Handlungswissen in minimalen Organisation. Nein, warten sie !Wir fangen noch mal an: die 20 Fußballer hatten keine Chance, ernsthaft zu trainieren. Die Verlockungen örtlichere kneipendzene waren zu groß. Das Feierabendbier schmeckte zu gut. Warum aber schafften es ausgerechnet zwei der Fußballer regelmäßig zum Training? Das war schon besser. So könnte doch ein Roman beginnen. Aber eigentlich ist das der Beginn eines Soziologischen Aufsatz, in dem es um den Zerfall von Organisationen geht. Dieser Aufsatz hat zwei Anfänge , den obigen im sperrigen Jargon des Faches, und den zweite. , der cher nach Hollywood klingt, die Brillanz des Aufsatzes liegt darin, dass er die beiden Anfänge zu einem Ende zusammenführt , das man als Leser fast bedauert, weil es auch das Endes eines großen intellektuellen Vergnügens bedeutet.",
