        "text": "Veröffentlicht hat den Text der amerikanische Soziologie Karl E.",
        "german": "Veröffentlicht hat den Text der amerikanische Soziologie Karl E.",
        "firstSentence": "Veröffentlicht hat den Text der amerikanische Soziologie Karl E.",
        "chinese": "这篇文章由美国社会学家卡尔·E·韦克发表。它之所以特别值得一提，是因为学术论文能给读者带 来阅读乐趣绝非理所当然。恰恰相反：人们常说学术语言丑陋、晦涩或浮夸，这几乎已成为一种 陈词滥调。对于某学科的学生来说，最令人恼火的障碍往往在于学习该学科的表达方式；而在毕 业论文中，考官会检验学生是否能够将原本可以更简单表达的内容，按照该学科的标准，用同样 抽象且空洞的措辞来表述。企业管理学手册常常用浮夸的英语陈述一些老生常谈，让那些仅受过 基础培训的零售商只能对此摇头叹息。学者们用复杂的语言在自己的思想周围筑起高墙，而学生 们却乐于模仿这种故作高深的姿态。这样做存在一种风险，即他们可能会因此败坏自己的文风— 即使他们实际上具备写作天赋也是如此。人们很容易推测，学术语言不过是一种可笑的外衣， 人们用它来代替通俗易懂的日常语言，以便在学术界显得可信。",
        "sentenceZh": "这篇文章由美国社会学家卡尔·E·韦克发表。",
        "summary": "这篇文章由美国社会学家卡尔·E·韦克发表。",
        "passage": "Veröffentlicht hat den Text der amerikanische Soziologie Karl E. Weick. Und er ist deshalb besonders erwähnenswert, weil es keinesfalls eine Selbstverständlichkeit ist , dass Wissenschaftliche Aufsätze den Leser Vergnügen bereiten. Ganz im Gegenteil: dass die Sprache Wissenschaft hässlich, Umständlich oder aufgeblasen sei. Ist beinahe schon ein Gemeinplatz. Für den Studenten eines Faches besteht häufig die ärgerlichste Hürde darin , dessen Ausdrucksweise zu erlernen ; in der Abschlussarbeit wird dann geprüft, ob er Dinge, die er zuvor einfacher hätten sagen können , auch genauso abstrakt und verblasen Formulieren kann, wie es Standard seines Faches ist. Handbücher der Betriebswirtschaft tragen oft in einen hochtrabenden English Banalitäten vor, über die der bloß angelernte Einzelhandelskaufmann nur den Kopf schütteln kann. Wissenschaftler bauen mit ihrer komplizierten Sprache Mauer um die eigenen Gedanken, Studenten ahmen ein solche Imponiergehabe gerne nach. Dabei besteht die Gefahr, dass sie sich den Stil verderben , und zwar selbst dann , wenn sie eigentlich ein Talent für das Schreiben habe. Die Vermutung liegt nahe , die Wissenschaftssprache sei nur ein albernes Gewand, das man statt der allgemein verständlich Alltagssprache benutzt , um Akademisch glaubwürdig auftraten zu können.",
