        "text": "Betrachtet man aber das Gesamtbild, lässt sich nur folgern: wer etwa im Studium nur Solche Perlen lesen möchte , wird es nicht bis zum Abschluss schaffen .Das Erlernen der Wissenschaftssprache kann man den Studenten nicht ersparen.",
