        "chinese": "但若从整体来看，只能得出这样的结论：那些在大学期间只想阅读此类“瑰宝”的人，是无 法顺利毕业的。学生们无法回避学习学术语言这一过程。不过，如果学术界有朝一日能更 加重视优雅且通俗易懂的文风，那将是一件好事，因为学术文本只有引起关注才能发挥作 用，而读者终究是需要被吸引的。",
