        "passage": "Betrachtet man aber das Gesamtbild, lässt sich nur folgern: wer etwa im Studium nur Solche Perlen lesen möchte , wird es nicht bis zum Abschluss schaffen .Das Erlernen der Wissenschaftssprache kann man den Studenten nicht ersparen. Doch schön wäre es, wenn die Wissenschaftswelt irgendwann mehr Wert auf eleganten und verständlichen Stil legen würde, Denn wissenschaftliche Texte können nur Wirkung entfalten ,wenn sie Beachtung finden und Leser wollen schließlich umworben werden.",
