        "passage": "Doch warum ist meine Abneigung gegen das Telefonieren so stark? Darüber haben ich mir in letzter Zeit häufig Gedanken gemacht. Ich empfinde es so, dass Anrufer es billigend in Kauf nehmen, andere zu stören :beim Schlafen, beim Duschen , beim Essen , beim allem. Denn jedes plötzliche Telefonklingeln erfordert sofortige Aufmerksamkeit. Es ist so , als würde jemand schreien: Platz da, jetzt komm ich. Das ist übergniffig und , ja ,rücksichtlos. Ohne Absprache nur für eine Plauderei anzurufen,das wirkt angesichts aller anderen Möglichenkeiten, als würde man sich rücksichtlos an der Theke beim Bäcker vordrängeln oder-- stärker ausgedrückt--als brettere man mit Blaulicht durch die Frontscheibe eines Supermarkt, um ein Päckchen Spaghetti zu kaufen.",
