        "german": "Wenn ich über das heutige Kommunikationsverhalten nachdenke, fällt mir allerdings ein merkwürdiger Widerspruch auf :Ist es niecht erstaunlich , dass alle ständig ein Gerät mit sich herumtrgen, das ursprünglich in erster Linie zum Telefonieren gedacht war - aber gerade diese Funktion immer weniger genutzt wird?",
        "firstSentence": "Wenn ich über das heutige Kommunikationsverhalten nachdenke, fällt mir allerdings ein merkwürdiger Widerspruch auf :Ist es niecht erstaunlich , dass alle ständig ein Gerät mit sich herumtrgen, das ursprünglich in erster Linie zum Telefonieren gedacht war - aber gerade diese Funktion immer weniger genutzt wird?",
        "chinese": "原文未提供中文释义",
