        "summary": "原文未提供中文释义",
        "passage": "Wenn ich über das heutige Kommunikationsverhalten nachdenke, fällt mir allerdings ein merkwürdiger Widerspruch auf :Ist es niecht erstaunlich , dass alle ständig ein Gerät mit sich herumtrgen, das ursprünglich in erster Linie zum Telefonieren gedacht war - aber gerade diese Funktion immer weniger genutzt wird? Das war bei den ersten Mobiltelefonen, die nur wenige Funktionen hatten und vor allem für bessere telefonische Erreichbarkeit sorgen sollten, noch anders. Wie dem auch sei: Den Gedanken oder das Gefühl u haben, Anrufe seien übergriffig, ist eine neuere Entwicklung. Stellen Sie sich doch einfach mal vor, wir wären wieder im Jahr 1985, Telefonisch erreichbar war man entweder auf der Arbeit, im Büro, oder nach Feierabend, im heimischen Wohnzimmer. Wenn man aber zu Hause war, hatte amn Ruhe, Lust und Zeit, und jeder Anruf war maximal eine Störung beim Abendessen, vermutlich aber eher eine willkommene Unterbrechung des Fernsehprogramms oder sonstiger Langeweile. Eine Ausnahmegab es allerdings, die heute fast schon komisch anmutet: In Deutschland galt die unausgesprochene Regel, dass man abends zwischen 20 Uhr und 20:15 Uhr nicht anruft - denn da saßen alle vor Fernseher und schauten die Nachrichten.",
