        "text": "Mit meiner Abnerigung gegen das Telefonieren stehe ich übrigens nicht alleine da.Bei unter Dreißigjährige und vor allem bei Jugendlich ist das persönliche Gespräch am Telefon zunehmend unbeliebt.",
        "german": "Mit meiner Abnerigung gegen das Telefonieren stehe ich übrigens nicht alleine da.Bei unter Dreißigjährige und vor allem bei Jugendlich ist das persönliche Gespräch am Telefon zunehmend unbeliebt.",
