        "summary": "原文未提供中文释义",
        "passage": "Mit meiner Abnerigung gegen das Telefonieren stehe ich übrigens nicht alleine da.Bei unter Dreißigjährige und vor allem bei Jugendlich ist das persönliche Gespräch am Telefon zunehmend unbeliebt. Die Hochschule für Angewandte Wissenschaften in Zürich hat herausgefunden, dass rund 30 Prozent der Jugendlichen die Telefonkunktion ihres Smartphones so gut wie gar nicht mehr nutzen. Der Grund dafür liegt allerdings nicht nur darin, dass Anrufe als übergriffig wahrgenommen werden. So erklärt Philippe Wampfler, Dozent für Fachdidaktik an der Universität Zürich: \"Während man beim Telefonieren gezwungen ist, sofort zu reagieren,kannman sich bei einer Sprachnachricht Zeit lassen.\" Sebastian Olbrich, stellvertretender Leiter des Zentrums für Soziale Psychiatrie an der Psychiatrie an der Psychiatrischen Universitätsklinik Zürich, erläutert:\" Beim Telefonieren kann man das Gegenüber nicht sehen und die Reaktionen somit schlechter abschätzen .Das kann Ängste hervorrufen. Zudem fürchten einige, etwas Falsches zu sagen, was man nicht korrigieren kann.\" Wer schreibt, habe dagegen die Möglichkeit, auch noach mal in Ruhe das Pro und Contra abzuwägen, bevor die Antwort abgeschickt wird.",
