        "number": "1",
        "paragraph": "A",
        "text": "Vor Präsentationen gibt es an der Uni kein Entkommen.",
        "german": "Vor Präsentationen gibt es an der Uni kein Entkommen.",
        "firstSentence": "Vor Präsentationen gibt es an der Uni kein Entkommen.",
        "chinese": "在大学里，演讲是无法避免的。如今，制作演讲幻灯片已被视为与读写同等重要的基本技 能，甚至更为重要，而在大教室和研讨室里，幻灯片已成为不可或缺的一部分。如今，每 一位大一新生在第一学期都被要求使用PowerPoint幻灯片来辅助自己的演讲。第一张幻灯片 通常显示演讲者的姓名，第二张写着：“欢迎光临”。到了第三张，同学们就开始走神，渐渐 进入甜美的梦乡。这种集体打瞌睡当然并非本意，但大家也能容忍。毕竟，睡着的人就不 会提出那些令人头疼的问题。演讲者随后若无其事地继续，照着幻灯片念着那些任何人都 能自己读出的内容。再配上几张图片、图表和表格来美化一下——这样，一场演讲就完成 了，听众的头不可避免地会垂下来，直到他们慢慢进入梦乡。",
        "sentenceZh": "在大学里，演讲是无法避免的。",
        "summary": "在大学里，演讲是无法避免的。",
        "passage": "Vor Präsentationen gibt es an der Uni kein Entkommen. Diese erstellen zu können gilt heutzutage als eine grundlegende Fähigkeit wie Lesen und Schreiben, fast noch wichtiger sogar, und aus Hörsälen und Seminarräumen sind die Folien nicht mehr wegzudenken. Von jedem Studienanfänger im ersten Semester wird heute erwartet, dass er sein Referat mit PowerPoint-Folien unterlegt. Die erste zeigt in der Regel den Namen des Referenten, auf der zweiten steht: \"Herzlich willkommen\". Nach der dritten schalten die Kommilitonen ab und verschwinden ins Reich der süßen Träume. Dieses kollektive Wegdämmern ist natürlich nicht beabsichtigt, wird aber toleriert. Wer schläft, stellt auch keine lästigen Fragen. Der Referent fährt dann unbeirrt fort und liest von seiner Folie vor, was jeder selbst lesen könnte. Dazu ein paar Bilder, Grafiken und Tabellen, die das Ganze aufhübschen – und fertig ist die Präsentation, bei der sich die Köpfe der Zuhörer unausweichlich nach unten neigen, bis sie langsam entschlummern.",
