        "number": "4",
        "paragraph": "D",
        "text": "Zu ergänzen ist noch, dass Präsentationen eine Gefahr mit sich bringen, die oft verkannt wird: Sie bieten die perfekte Tarnung für Unsicherheit, inhaltliche Leere und fehlendes Wissen.",
        "german": "Zu ergänzen ist noch, dass Präsentationen eine Gefahr mit sich bringen, die oft verkannt wird: Sie bieten die perfekte Tarnung für Unsicherheit, inhaltliche Leere und fehlendes Wissen.",
        "firstSentence": "Zu ergänzen ist noch, dass Präsentationen eine Gefahr mit sich bringen, die oft verkannt wird: Sie bieten die perfekte Tarnung für Unsicherheit, inhaltliche Leere und fehlendes Wissen.",
        "chinese": "还需要补充的是，演讲往往伴随着一种常被忽视的风险：它们为缺乏自信、内容空洞和知 识匮乏提供了完美的掩护。如果没有幻灯片，许多演讲就会像舒芙蕾一样瞬间塌陷，因为 它们只不过是将一些陈词滥调拼凑在一起罢了。对听众而言，这意味着生命时间的浪费； 而演讲者却沉浸在虚假的安全感中。他自以为掌握了主题，对内容了如指掌，尽管实际上 他只是将一些平庸的信息拼凑起来并照本宣科罢了。最迟在考试时，这一点就会让他自食 其果。此外还有一点尤为严重：那些在演讲中总是紧盯着幻灯片照本宣科的人，几乎无法 学会自由演讲，也难以培养出从容自若的演讲风格。因此，他们实际上剥夺了自己掌握那 些本可在职业生涯中助其进步的技能的机会。",
        "sentenceZh": "还需要补充的是，演讲往往伴随着一种常被忽视的风险：它们为缺乏自信、内容空洞和知 识匮乏提供了完美的掩护。",
        "summary": "还需要补充的是，演讲往往伴随着一种常被忽视的风险：它们为缺乏自信、内容空洞和知 识匮乏提供了完美的掩护。",
        "passage": "Zu ergänzen ist noch, dass Präsentationen eine Gefahr mit sich bringen, die oft verkannt wird: Sie bieten die perfekte Tarnung für Unsicherheit, inhaltliche Leere und fehlendes Wissen. Ohne Folien würden viele Vorträge in sich zusammenfallen wie ein Soufflé, reihen sie doch nur Allgemeinplätze aneinander. Für die Zuhörer bedeutet dies verschwendete Lebenszeit, der Referent dagegen wiegt sich in falscher Sicherheit. Er glaubt, ein Thema zu beherrschen, es inhaltlich durchdrungen zu haben, obwohl er letztlich nur banale Informationen zusammengestellt und vorgelesen hat. Spätestens in einer Prüfung könnte ihm dies auf die Füße fallen. Und was außerdem schwer wiegt: Wer sich in einem Vortrag immer nur an seinen Folien entlanghangelt, kann es kaum erlernen, frei zu sprechen und einen souveränen Vortragsstil zu entwickeln. Er nimmt sich also die Chance, Fähigkeiten zu erwerben, die ihn im Berufsleben voranbringen könnten.",
