        "firstSentence": "Eltern können anstrengenden sein.",
        "chinese": "义来提供信息？ 父母有时确实让人头疼。凡是在幼儿园、学校或体育俱乐部工作过的人都深有体会。健康的饮 食、理想的成绩、最优质的培养——这些都是忧心忡忡的父母们所追求的。当然，所有父母都希 望自己的孩子能成为最优秀的人，这一点自古以来从未改变。然而： 如今许多父母的育儿方式— 部分表现为强迫性或偏执性的过度保护，以及对儿童或青少年事务的过度干涉——令人感到陌 生和惊讶。这些过度溺爱的父母总是紧跟在孩子身边，时刻监视并保护他们， 就像一架侦察直升 机——这也正是他们被称为“直升机父母”的原因吗？他们因此引发的种种风波，简直成了轶事笑 谈中取之不尽的素材。",
        "sentenceZh": "义来提供信息？",
        "summary": "义来提供信息？",
        "passage": "Eltern können anstrengenden sein. Wer im Kindergarten, in der Schule oder im Sportverein tätig ist weiß das. Das richtige Essen, die passenden Noten, die beste Förderung - all das fordern besorgte Mütter und Väter ein. Natürlich wünschen sich alle Eltern für ihre Sprösslinge das biste , und das was sicher zu allen Zeiten so. Dennoch: Der Erziehungsstil so mancher Eltern von heute, der geprägt ist von zum Teil zwanghafter oder paranoider Überbehütung und exzessiver Einmischung in die Angelegenheiten des Kinds oder des Heranwachsenden, weckt Befremden und Verwunderung, ist es eigentlich nicht recht merkwürdig, dass diese überfürsorglichen Eltern sich ständig in der Nähe ihrer Kinder aufhalten , umsiedeln zu überwachen und zu behüten, ähnlich wie ein Beobachtungs-Hubschrauber-weshalb Sie auch Helikopter-Eltern genannt werden ? Mit dem Wirbel den sie dabei veranstalten, sind sie ein schier unerschöpfliches Thema für Anekdoten.",
