        "firstSentence": "Etwa die von dem Siebtklässler, der mit zwei Mädchen ins Kino gehen wollte.",
        "chinese": "比如那个想和两个女孩一起去看电影的七年级学生。不过他没想到父母会提出一个条件：母亲会 乔装打扮跟在他们后面。对一个青少年来说，这可真是一次轻松的出游！当伪装快要败露时，这 位女士便假装成一位邻居。还有一件事也不错：有些父母因为担心苹果掉在孩子头上，竟把花园 里那棵50年的苹果树砍掉了。至于成绩不佳时，有些家庭甚至直接威胁老师要找律师——这早已 不是什么新鲜事了，更不用说他们还会直接向学校监管部门或教育部投诉。还有一类家长更是令 人十分反感，他们开着豪车把心爱的孩子直接送到校门口，肆无忌惮地堵塞人行道，从而给步行 上学的其他孩子带来巨大危险。正是这些家长，在学校的家长会上总得被反复提醒：请不要干涉 孩子们的职业培训，也不要像影子一样一直跟到大学，甚至在那里——仿佛这是世上最理所当然 的事——打听第一次家长会何时举行。",
        "sentenceZh": "比如那个想和两个女孩一起去看电影的七年级学生。",
        "summary": "比如那个想和两个女孩一起去看电影的七年级学生。",
        "passage": "Etwa die von dem Siebtklässler, der mit zwei Mädchen ins Kino gehen wollte. Allerdings hatte er nicht mit seinen Eltern gerechnet, die eine Bedingung stellten: Die Mutter würde ihnen inkognito folgen. Was für ein entspannter Ausflug für einen Teenager! Als die Deckung aufzufliegen drohte, stellte sich die Frau als eine Nachbarin vor. Auch nicht schlecht: Eltern,die einen 50 Jahren alten Apfelbaum im Garten Fällen,weil ihrem Kind kein Apfel auf den Kopf fallen sollte. Und dass bei schlechten Noten so manche Familien den Lehrern glich mit dem Anwaltdroht ist ohnehinnichts neues mehr .wenn sie sich nichtglich direkt an die Schulaufsicht oder das Ministerium wenden. Ganz unangenehmen sind auch solche altern , die Ihre Lieblinge in dicken Autos bis vor die Schultür Karren Rücksichtslos versperren sie Gehwege und bringen damit andere Kinder, die zu Fuß kommen , in Grüße Gefahr. Das sind die gliche Eltern , die auf Elternabenden in der Schule regelmäßig darum gebeten werden müssen , doch bitte nicht die Berufsausbildung ihrer Kinder einmischen oder ihren wie ein Schatten bis an die Universität folgen und sich dort womöglich noch - als wäre es das Selbstverständlichste auf der Welt - erkundigen, wann der erste Elternabend stattfindet.",
