        "german": "Wichtig ist , die Kinder Fehler machen zu lassen.",
        "firstSentence": "Wichtig ist , die Kinder Fehler machen zu lassen.",
        "chinese": "重要的是，要让孩子犯错误。他们也必须偶尔经历失败，也需要偶尔擦破一次膝盖。只有这样， 他们才能学会在未来避免更多的错误。因为，为了培养心理上的抵抗能力——也就是所谓的“心理 韧性”——孩子也必须偶尔经历一次失误。这就类似于重新站起来。如果一个孩子从来不被允许绊 倒，甚至不被允许摔倒，因为人们总是在引导他，并且提前把他接住，那么以后，当父母不再站 在他身后、不能再像操纵木偶一样引导他的时候，他不仅必须独自经历第一次摔倒，没有安慰， 也没有支撑，而且他也不知道怎样立刻重新站起来并继续前进，而只会继续躺在那里。因此，人 们应该让孩子自己积累经验，而不应该替他们解决每一个需要克服的困难。",
        "sentenceZh": "重要的是，要让孩子犯错误。",
        "summary": "重要的是，要让孩子犯错误。",
        "passage": "Wichtig ist , die Kinder Fehler machen zu lassen. Sie müssen auch mal scheitern , brauchen mal ein aufgeschürftes Kreise Nur so können sie lernen , zukünftig weitere Fehler zu vermeiden. Denn um seelische Widerstandsfähigkeit- die sogenannte Resilienz- zu erlernen, muss ein Kind auch mal einen Fehltritt erleben. Es ist ähnlich dem aufstehen. Darf ein Kind nie stolpern oder gar hinfallen, weil man es lenkt und vorzeige auffängt, wird es später, wenn die Eltern nicht hinter ihm stehen und es wie eine Marionette führen , nicht nur den ersten Sturz allein erleben müssen , ohne Trost oder Halt , es wird auch nicht wissen , wie es glich wider aufstehen und weitergehen kann , sonderneinfach liegen bleiben.Mann sollte Kinderalso eigene Erfahrungen machen lassen und ihnen nicht jede Schwierigkeit , die es zu überwinden gilt , abnehmen",
