        "text": "Nach Einschätzung des Psychotherapeuten Martin Kleiser aus Freiburg tendieren rund 15-20% der Eltern zu extremer Überbehütung.",
        "german": "Nach Einschätzung des Psychotherapeuten Martin Kleiser aus Freiburg tendieren rund 15-20% der Eltern zu extremer Überbehütung.",
        "firstSentence": "Nach Einschätzung des Psychotherapeuten Martin Kleiser aus Freiburg tendieren rund 15-20% der Eltern zu extremer Überbehütung.",
        "chinese": "根据弗赖堡心理治疗师Martin Kleiser的估计，大约15%—20%的父母倾向于过度保护孩子。 其中一个原因是他们对孩子未来的担忧。许多教育工作者认为，这种担忧在独生子女家庭 中尤其明显。那些孩子就读于全日制学校的“直升机父母”也会有这种情况。在这种情况 下，过度保护是父母的一种补偿行为。由于父母一整天都不能亲自陪伴孩子，他们便会在 下班后给予孩子大量的爱和关怀。教育工作者Simon Mann则认为，学校制度应该对此负 责，因为这一制度几乎是在要求父母参与，同时许多家庭在这一制度中感到自己孤立无 援。然而，来自汉堡的儿童和青少年精神科医生Michael Schulze对此看得更加轻松。他表 示：“我非常高兴父母变得更加关心孩子。完全没有任何迹象表明，我们的孩子变得更加缺 乏独立生活能力或者心理上更加不稳定。”他认为，不应该对许多家庭中原本非常良好的亲 子关系提出质疑。",
        "sentenceZh": "根据弗赖堡心理治疗师Martin Kleiser的估计，大约15%—20%的父母倾向于过度保护孩子。",
