        "passage": "Nach Einschätzung des Psychotherapeuten Martin Kleiser aus Freiburg tendieren rund 15-20% der Eltern zu extremer Überbehütung. Ein Grund dafür sei die Sorge um die Zukunft der Kinder. Viele Pädagogen sehen diese Sorge besonders in ( ein Kind Familie). Helikopter- Eltern hätten , deren Schützlinge auf eine Ganztagsschule gingen. In diesem Fall diene das Helikoptern als Ausgleichshandlung. Da die Eltern den ganzen Tag nicht persönlich für ihre Kinderda seien , überschütteten sie ihre Sprösslinge nach Feierabend mit liebe und Fürsorglichkeit. Die Pädagogen Simon Mann dagegen macht das Schulsystem verantwortlich, das die Mitarbeit der Eltern geradezu einfordere und in dem sich viele Familienalleingelassen fühlen. Der Kinder und Jugendpsychiater Michael Schulze aus Hamburg jedoch sieht die Sachlage entspannter: Ich freue mich sehr darüber, dass Eltern fürsorglicher geworden sind ,,meint er“ Es gibt überhaupt keine Hinweise, dass unsere Kinder lebensunfähiger oder psychisch instabiler geworden sind. Man dürfte die Beziehung , die in vielen Familien sehr gut sei , nicht diskutieren.",
