        "chinese": "不过，扪心自问，谁没有曾经发现自己在照顾孩子这件事上做得有些过头呢？那些相信自己孩子 能力的父母，并不需要能够通过GPS定位孩子的手机。他们知道，自己可以信赖孩子。孩子需要 勇气，也需要信任。这对我们这些父母来说并不容易。也许，回忆一下自己的童年会有所帮助。 想想当年和其他孩子一起在花园里搭建小屋时的快乐；想想那个滚进池塘里的球，尽管不被允 许，我们还是把它捞了出来；再想想那些曾经被我们克服的许许多多小危机。我们的父母当时是 更加放松、更加不担心，还是只是考虑得没有那么多？无论如何，他们更加勇敢。那时候，人们 更经常听到这样的话：“哎呀，我的孩子自己能做到。”如今我们认识到，在这种从容的态度背 后，其实隐藏着一种非常自信而成熟的态度：这种态度建立在相信自己的孩子以及相信自己判断 能力的基础之上。对此思考得越多，人们就越会对我们的父母通过这种方式表现出来的坚强产生 敬意。因为，让幼儿园的孩子和小学低年级的孩子独自在外面四处活动，根本不是一件容易的事 情。但是，也许我们也能够重新学会这样做。",
