        "passage": "Doch Hand aufs Herz,wer hat sich nicht schon mal selbstdabei ertappt, wie er es mit der Fürsorge übertreibt? Eltern , die ihren Kinder etwas zutrauen , brauchen keinen Handys , die per GPS das Kind orten können. Sie wissen , dass sie sich auf ihren Nachwuchs verlassen können. Kinder brauchen Mut und Zutrauen. Das ist nicht einfach für uns Eltern. Vielleicht hilft es sich an die eigene Kindheit zu erinnern. An die Freude daran , im Garten mit die anderen Kinder eine Hütte zu bauen , an den Ball , der in den Tümpel gerollt war und den man herausfischte , obwohl das verboten war. An vielen kleine Krisen, die gemeistert wurden, waren unsere Eltern lockerer, unbesorgter oder unbedarfter ? Auf jeden Fall mutiger. Sätze wie : Ach mein Kind kann das schon, hörte man häufiger.Heute erkennen wir, dass sich hintereiner solchen Gelassenheit eine sehr souveräne Haltung verbringt: diese beruht auf der Fähigkeit, den eigenen Kindern wie auch dem eigenen Urteil zu vertrauen. Je mehr man darüber nachdenkt , umso mehr Respekt empfindet man vor der Stärke , die unsere Eltern damit demonstriert haben. Denn es ist überhaupt nicht einfach, Kindergartenkinder und kleine Grundschüler alleine durch die Gegend Stromernzu lassen. Aber vielleicht können auch wir es wiederlernen.",
