        "chinese": "吗？/ 作者提供了明确的信息吗？ 有些孩子被呵护得像玻璃球一样。从摇篮到大学教室，这些儿女们全天候受到照料， 由此引发的荒诞后果如今已汇编成书。但这些“直升机父母”究竟是谁？做父母的确实让 人头疼。凡是在幼儿园、学校或体育俱乐部工作过的人，都深有体会。合适的饮食 只吃有机食品）、理想的成绩（至少要“良好”）、最优质的培养（只为自家孩子）— 这些都是忧心忡忡的父母们所要求的。对这些孩子来说，必须是最好的、最漂亮 的、最出色的，否则就不行；而他们之所以让人头疼，正是因为他们太过出色了。这 些围着心爱孩子大张旗鼓转来转去的成年人，也被称为“直升机父母”。他们制造的这番 骚动，成了轶事中取之不尽的话题。",
