        "chinese": "笑？ 想听些例子吗？比如那个想和两个女孩去电影院的七年级学生。不过他没料到父母会提出 一个条件：母亲会乔装打扮跟在他们后面。这可真是一次轻松的出游，尤其是对一个青少 年来说！当伪装快要败露时，这位女士便自称是邻居。还有个也不错的例子： 还有些家长 因为担心苹果掉在孩子头上，竟把花园里那棵50岁的苹果树砍掉了。至于成绩不佳时，有 些家庭直接威胁老师要找律师——这早已不是什么新鲜事了，甚至还有人直接向学校监管 部门或教育部投诉。那些开着豪华轿车把心爱的孩子直接送到校门口的家长也令人恼火。 他们肆无忌惮地堵塞人行道，给步行上学的其他孩子带来了巨大危险。",
