        "chinese": "副驾驶有时确实很烦人。但他们真的危险吗？有时，一辆载着一对夫妇的奔驰车会撞上车库墙 壁；有时，警察会拦下一名超速驾驶者，而该司机声称自己是因为车内发生激烈夫妻争吵才开 得过快的。与副驾驶发生争执是交通警察报告中屡见不鲜的起因。幸运的是，并非每次都会发 生事故。副驾驶座脚垫的状况有时能透露出争吵的细节——争吵就发生在脚垫受损的那个确切 位置。副驾驶总是会跟着踩刹车。一张布满孔洞的脚垫本可以作为“恐惧副驾驶俱乐部”的标 志，不过这个俱乐部（目前）还不存在。该俱乐部的年度聚会恐怕会充斥着对那些不顾他人或 顽固不化的司机的抱怨和哀叹。难道司机不会把任何善意的限速提醒都视为对自己的根本性批 评吗？他是否会捕捉到每一次的紧张反应，并以一通咒骂作为回应？那些不得不忍受副驾驶让 友谊中的紧张关系不断升级的人，同样会为自己的性命感到担忧。脚垫上布满了拳头大小的 洞。一位刚拿到驾照的新手正想展示一下自己的本事。",
        "sentenceZh": "副驾驶有时确实很烦人。",
        "summary": "副驾驶有时确实很烦人。",
        "passage": "Beifahrer können nervig sein. Aber sind sie auch gefährlich? Mal knallt ein Mercedes, in dem ein Paar sitzt,gegen eine Garagenwand, mal stoppt die Polizei einen Raser, der angibt, er sei wegen eines heftigenEhestreits im Auto zu schnell gefahren. Streit mit dem Beifahrer ist ein notorisches Motiv in den Berichtender Verkehrspolizei. Glücklicherweise kommt es nicht immer zu Unfällen. Der Zustand der FuBmatte desBeifahrers verrät manchmal etwas über das Ausmal des Streits, der exakt an der Stelle stattfand, wo dieFuBmatte beschädigt wurde. Beifahrer immer mitbremst. Eine durchlocherte Matte ware ein geeignetesLogo fur den Club der verangstigten Beifahrer, den es allerdings (noch) nicht gibt. Seine Jahrestreffen wären erfüllt von Jammern und Wehklagen über rücksichtslose oder unbelehrbare Fahrer. Wird nicht jederwohlgemeinte Hinweis auf ein Tempolimit vom Fahrer als Fundamentalkritik gewertet? Registriert er jedesZusammenzucken und antwortet mit Schimpftiraden? Angst um ihr Leben haben auch Leute, die esaushalten müssen, dass der Beifahrer die Spannungen in der Freundschaft eskalieren lässt. In der FuBmattefinden sich faustgroBe Löcher. Ein Fuhrerscheinneuling will zeigen, was er draufhat.",
