        "text": "Doch wir Fahrer haben gute Gründe, manchen Beifahrer zum Teufel zu wünschen.",
        "german": "Doch wir Fahrer haben gute Gründe, manchen Beifahrer zum Teufel zu wünschen.",
        "firstSentence": "Doch wir Fahrer haben gute Gründe, manchen Beifahrer zum Teufel zu wünschen.",
        "chinese": "不过，我们这些司机确实有充分的理由想把某些副驾驶送上西天。我深有体会：我亲爱的妻子 连在车里都会打鼾，而且每到周日，她就会变成那种非得在副驾驶座上解决自己那套陈年“权 威问题”的司机。而且她总是爱说那些自以为是的话，偏偏是她：“亲爱的，再也开不了更环保 了。”变速箱向你问好。确实，有时驾驶风格会稍微激进一些——但这难道不值得信任吗？还 有，一旦在弯道上稍微加速一点，她就会表现得那般夸张地紧张起来。对有些人来说，同乘一 车是纯粹的乐趣，对另一些人来说却纯粹是压力。请别误会：我和妻子结婚16年了，在日常生 活中我们是配合默契的搭档。但在车里，我们的婚姻却面临严峻考验。",
        "sentenceZh": "不过，我们这些司机确实有充分的理由想把某些副驾驶送上西天。",
        "summary": "不过，我们这些司机确实有充分的理由想把某些副驾驶送上西天。",
        "passage": "Doch wir Fahrer haben gute Gründe, manchen Beifahrer zum Teufel zu wünschen. Ich kenne das aus eigener Erfahrung: Meine liebe Gattin schnarcht selbst im Auto und sonntags ist sie eine Fahrerin, die ihr altes Autoritätsproblem ausgerechnet auf dem Beifahrersitz aufarbeiten muss. Und immer diese atzenden Besserwissersprüche, ausgerechnet von ihr:, Grüner wird's nicht, Schatz.\" Schönen GruB vom Getriebe.Es stimmt ja, dass man manchmal etwas sportlich unterwegs ist - aber wo bleibt das Vertrauen? Und diesestheatralische Verkrampfen, wenn man mal etwas zügig durch die Kurve fährt. Fur die einen ist diegemeinsame Autofahrt pures Vergnügen, für die anderen purer Stress. Verstehen Sie mich nicht falsch:Meine Frau und ich sind seit 16 Jahren verheiratet und im normalen Leben ein eingespieltes Team. Aber imAuto wird unsere Ehe auf eine harte Probe gestellt.",
