        "text": "Die Beifahrerfrage ist ein bedauerlicherweise zu wenig beachtetes Thema der Verkehrssicherheit.",
        "german": "Die Beifahrerfrage ist ein bedauerlicherweise zu wenig beachtetes Thema der Verkehrssicherheit.",
        "firstSentence": "Die Beifahrerfrage ist ein bedauerlicherweise zu wenig beachtetes Thema der Verkehrssicherheit.",
        "chinese": "副驾驶问题是交通安全领域中一个遗憾地未受到足够重视的话题。当技术故障影响安全时，其 对驾驶员造成的后果会被细致入微地研究。但如果问题出在副驾驶身上呢？关于副驾驶在交通 参与者行为中扮演何种角色的研究却寥寥无几。然而，在这些“铁皮盒子”里，权力博弈正在上 演。社会学家将汽车描述为一个“轮子上的动态社会系统”，其中社会关系可能会对驾驶产生重 大影响。德累斯顿工业大学的交通心理学家伯恩哈德·施拉格（Bernhard Schlag）研究了驾驶 员与副驾驶之间互动的心理和社会学方面。",
        "sentenceZh": "副驾驶问题是交通安全领域中一个遗憾地未受到足够重视的话题。",
        "summary": "副驾驶问题是交通安全领域中一个遗憾地未受到足够重视的话题。",
        "passage": "Die Beifahrerfrage ist ein bedauerlicherweise zu wenig beachtetes Thema der Verkehrssicherheit. Welche Folgen es für den Fahrer hat, wenn ein technisches Problem die Sicherheit beeinträchtigt, wird bis ins Kleinste untersucht. Doch was passiert, wenn der Beifahrer das Problem ist? Untersuchungen zur Rolie des Beifahrers in unserem Verkehrsteilnehmerverhalten sind rar. Dabei werden in den Blechkisten Machtspiele ausgetragen.Soziologen beschreiben das Auto als ein dynamisches soziales System auf Rädern, in dem die sozialenBeziehungen einen bedeutsamen Einfluss auf das Fahren haben können. Bernhard Schlag, Verkehrspsychologe ander TU Dresden, hat die psychologischen und soziologischen Aspekte des Zusammenspiels von Fahrer undBeifahrer untersucht.",
