        "text": "Das Ergebnis zeigt: Beifahrer können zur Verkehrssicherheit beitragen oder diese gefährden.",
        "german": "Das Ergebnis zeigt: Beifahrer können zur Verkehrssicherheit beitragen oder diese gefährden.",
        "firstSentence": "Das Ergebnis zeigt: Beifahrer können zur Verkehrssicherheit beitragen oder diese gefährden.",
        "chinese": "难？ 结果表明：副驾驶乘客既可以为交通安全作出贡献，也可能危及交通安全。关于这一点，我们应 该认真思考一下。副驾驶乘客睡觉，不正是副驾驶可能产生双重作用的最好例子吗？当我作为驾 驶员感受到同行者对我的信任时，我会感到高兴。同时，对方均匀的呼吸也会让我平静下来。但 这种影响也可能非常强烈，以至于我受到睡着的乘客影响，自己也睡着。而短暂打瞌睡确实令人 害怕。根据德国交通安全委员会的估计，许多事故都可以归因于这种情况，高速公路上的许多事 故也是由短暂打瞌睡造成的。 另一个例子是副驾驶伸手去抓方向盘。对于驾驶员来说，副驾驶几乎没有比突然出手帮助控制方 向更加越俎代庖的行为了，例如，当副驾驶觉得汽车与一辆停放的车辆距离太近时。然而，恰恰 就是这样一种“越界行为”，让两年前我父亲的一位同事Jens Weinrich成为了我心目中的英雄。当 时Weinrich坐在副驾驶座上和我父亲一起出行，我父亲突然身体不适并失去了意识。Weinrich牢牢 抓住方向盘，费力地调整身体，最终安全地把汽车开到了路边。他的反应不仅避免了一场事故， 而且还表明，在这种情况下，人们实际上并不一定只能无所作为地看着。这样的干预不仅避免了 一场事故，也说明我们不能一概而论，究竟什么样的副驾驶行为能够促进安全，什么样的行为反 而会威胁安全。",
        "sentenceZh": "难？",
        "summary": "难？",
        "passage": "Das Ergebnis zeigt: Beifahrer können zur Verkehrssicherheit beitragen oder diese gefährden. Daruber sollten wireinmal nachdenken. Ist der Beifahrerschlaf nicht das schönste Beispiel für die ambivalente Wirkung, die ein Beifahrer erzielen kann? Wenn ich als Fahrer das Vertrauen meines Mitreisenden spure, bin ich glücklich.Gleichzeitig wirkt die Gleichmäßigkeit des Atmens auch beruhigend auf mich. Moglicherweise kann dieser Effektso stark sein, dass ich vom Schlafenden angesteckt werde und selbst einschlafe. Und der Sekundenschlaf istzurecht gefuirchtet. Nach Schatzungen des Deutschen Verkehrssicherheitsrats sind sehr viele Unfalle daraufzuruckzufuhren. auf Autobahnen durch Sekundenschlaf verursacht. Ein anderes Beispiel ist der Griff ins LenkradSchlimmer kann der Beifahrer den Fahrer nicht bevormunden, als durch eine spontane Lenkhilfe, zum Beispiel,wenn der Abstand zu einem parkenden Auto zu gering scheint. Und doch war es just eine solche Untat\", die vorzwei Jahren einen Kollegen meines Vaters, Jens Weinrich, zu meinem Helden machte. Weinrich war als Beifahrermit meinem Vater unterwegs, als dieser plotzlich einen Schwacheanfall erlitt und das Bewusstsein verlor.Weinrich griff eisern ins Lenkrad und lenkte das Auto mit muhevollen Verrenkungen sicher an den StraBenrand.Seine Reaktion verhinderte nicht nur ein Ungluck, sie zeigte auch, dass man tatsachlich nicht tatenlos zusehenmuss. Eingreifen verhinderte nicht nur ein Ungluick, sondern zeigte auch, dass man nicht pauschal sagen kann,welches Beifahrerverhalten die Sicherheit fordert und welches sie eher bedroht.",
