        "chinese": "一小块玛德琳蛋糕——也就是一种法国沙蛋糕——就足够了：将这块点心在椴花茶中浸软后品 尝，让马塞尔·普鲁斯特著名小说系列《追忆似水年华》中的主人公重新体验到了童年时那种令人 愉悦的幸福感。世界文学中这一著名场景所描绘的体验，想必很少有人会感到陌生：试想一下， 当你咬下一口苹果蛋糕时，它的味道竟与你童年时挚爱的祖母常烤的那款一模一样。毫无疑问， 你会感受到，这种熟悉的味道让你心中涌起温暖与安全感。你仿佛回到了那个心满意足的时刻— 仅仅因为咬了一口苹果派。科学界长期以来一直推测，食物会影响我们的情绪。",
        "sentenceZh": "一小块玛德琳蛋糕——也就是一种法国沙蛋糕——就足够了：将这块点心在椴花茶中浸软后品 尝，让马塞尔·普鲁斯特著名小说系列《追忆似水年华》中的主人公重新体验到了童年时那种令人 愉悦的幸福感。",
        "summary": "一小块玛德琳蛋糕——也就是一种法国沙蛋糕——就足够了：将这块点心在椴花茶中浸软后品 尝，让马塞尔·普鲁斯特著名小说系列《追忆似水年华》中的主人公重新体验到了童年时那种令人 愉悦的幸福感。",
        "passage": "Ein kleines Stück Madeleine, eines französischen Sandkuchens also, genügte: Der Genuss dieses Gebäckstücks, in Lindenblütentee aufgeweicht, erweckte in dem Helden von Marcel Prousts berühmtem Romanzyklus „Auf der Suche nach der verlorenen Zeit“ ein wohliges Glücksgefühl wieder zum Leben, das er aus seiner Kindheit kannte. Diese berühmte Szene aus der Weltliteratur beschreibt eine Erfahrung, die den wenigsten fremd sein dürfte: Stellen Sie sich vor, Sie beißen in ein Stück Apfelkuchen, der genauso schmeckt wie der, den Ihre geliebte Großmutter in Ihrer Kindheit immer gebacken hat. Sicher fühlen Sie,wie der bekannte Geschmack Gefühle von Wärme und Geborgenheit in Ihnen aufsteigen lässt. Sie fühlen sich zurückversetzt in eine Situation, in der Sie rundum zufrieden waren – und zwar allein durch einen Biss in den Apfelkuchen. Die Wissenschaft geht schon länger der Vermutung nach, dass Nahrung unsere Stimmung beeinflusst.",
