        "text": "Und zwar schon seit Jahrtausenden: Hippokrates von Kos, der berühmteste Arzt der Antike, gab Schwermütigen eine Empfehlung, die heute sehr viel Heiterkeit hervorrufen dürfte.",
        "german": "Und zwar schon seit Jahrtausenden: Hippokrates von Kos, der berühmteste Arzt der Antike, gab Schwermütigen eine Empfehlung, die heute sehr viel Heiterkeit hervorrufen dürfte.",
        "firstSentence": "Und zwar schon seit Jahrtausenden: Hippokrates von Kos, der berühmteste Arzt der Antike, gab Schwermütigen eine Empfehlung, die heute sehr viel Heiterkeit hervorrufen dürfte.",
        "chinese": "而且这种情况其实早在几千年前就已经存在：古希腊最著名的医生——科斯的希波克拉底——曾 经给情绪低落的人提出过一个建议，而这个建议放到今天大概会引起很多人的开心。他们应该喝 驴奶，因为这可以驱散悲伤；相反，运动对于疲惫的心灵来说却是毒药。 即使这个出于好意的建 议大概会让每一个不喜欢运动的人都感到高兴——终于有了一个偷懒的好理由，而且这个理由还 是出自一位不可撼动的权威之口！——不过，如今医学界已经有充分的理由不再认可驴奶这种说 法。 然而，古代学说中还是包含着一点真理。因此，人们现在已经很少再怀疑，巧克力能够产生 幸福感，面食能够驱散沮丧，而坚果能够滋养神经。长期以来，传统医学一直对“吃东西实际上远 远不只是为身体提供营养，而且还会影响人的心理”这一观点持批判态度，不过如今它已经开始修 正自己的立场。越来越多的科学家正在研究，正确的饮食是否能够使人心情愉快，或者减轻心理 上的痛苦。",
        "sentenceZh": "而且这种情况其实早在几千年前就已经存在：古希腊最著名的医生——科斯的希波克拉底——曾 经给情绪低落的人提出过一个建议，而这个建议放到今天大概会引起很多人的开心。",
        "summary": "而且这种情况其实早在几千年前就已经存在：古希腊最著名的医生——科斯的希波克拉底——曾 经给情绪低落的人提出过一个建议，而这个建议放到今天大概会引起很多人的开心。",
        "passage": "Und zwar schon seit Jahrtausenden: Hippokrates von Kos, der berühmteste Arzt der Antike, gab Schwermütigen eine Empfehlung, die heute sehr viel Heiterkeit hervorrufen dürfte. Eselsmilch sollten sie trinken,denn das vertreibe die Traurigkeit, Sport dagegen sei Gift für die ermüdete Seele. Auch wenn dieser wohlgemeinte Rat jeden Bewegungsmuffel freuen dürfte – endlich mal ein guter Grund für die Faulheit,und dann noch aus dem Mund einer unantastbaren Autorität! –, ist die Medizin von Eselsmilch mittlerweile wohl aus gutem Grund abgekommen. Ein Körnchen Wahrheit steckt dennoch in den Überlegungen, die der antike Gelehrte verfolgte. So wird nur selten angezweifelt, dass Schokolade Glücksgefühle erzeugt,Nudeln Frust vertreiben und Nüsse Nervennahrung sind. Dass Essen wohl tatsächlich weit mehr als die Zufuhr von Nährstoffen für den Körper ist und auch die Psyche beeinflusst, betrachtete die Schulmedizin lange Zeit kritisch, doch mittlerweile beginnt sie ihre Position zu revidieren. Immer mehr Wissenschaftler untersuchen, ob das richtige Essen gute Laune machen oder seelisches Leid mindern kann.",
