        "firstSentence": "Beinahe hätten wir für unsere achtjährige Tochter Lea eine Smartwatch gekauft.",
        "chinese": "我们差点就给八岁的女儿莉娅买了一块智能手表。家里对此意见不一：一方面是我的妻子、我们 十六岁的儿子卢卡斯以及莉娅——她早已对这个新玩具充满期待；另一方面则是我，作为父亲。 我的妻子对能随时追踪莉娅位置的想法非常兴奋。卢卡斯则根本无法想象没有智能手表的生活。 尽管如此，我还是在最后一刻成功阻止了这款儿童监控工具的引入。因为就连我妻子也不喜欢这 样一种想法：莱娅在业余时间只会沉迷于智能手表，而不是尽情奔跑玩耍。现在，莉亚上学时依 然只带我的旧手机，以便在紧急情况下给我们打电话。",
        "sentenceZh": "我们差点就给八岁的女儿莉娅买了一块智能手表。",
        "summary": "我们差点就给八岁的女儿莉娅买了一块智能手表。",
        "passage": "Beinahe hätten wir für unsere achtjährige Tochter Lea eine Smartwatch gekauft. Es gab bei uns zuhause verschiedene Meinungen darüber: Auf der einen Seite standen meine Frau, unser sechzehnjähriger Sohn Lukas und Lea, die sich schon auf dieses neue Spielzeug freute. Auf der anderen Seite ich, der Vater. Meine Frau war begeistert von der Idee, jederzeit Leas Standort tracken zu können. Lukas konnte sich ein Leben ohne Smartwatch sowieso nicht mehr vorstellen. Dennoch konnte ich die Einführung dieses Kinderüberwachungs-Tools in letzter Minute noch einmal abwenden. Denn die Vorstellung, dass Lea sich in ihrer Freizeit nur mit der Smartwatch beschäftigen würde, statt sich auszutoben und zu spielen, gefiel auch meiner Frau nicht. Wenn Lea zur Schule geht, hat sie nun auch weiterhin nur mein altes Handy dabei, mit dem sie uns in dringenden Fällen anrufen kann.",
