        "text": "Wie kann man zukünftig eine Balance zwischen einer naturnahen Lebensweise in den Städten und den Bedürfnissen der Stadtbewohner erreichen?",
        "german": "Wie kann man zukünftig eine Balance zwischen einer naturnahen Lebensweise in den Städten und den Bedürfnissen der Stadtbewohner erreichen?",
        "firstSentence": "Wie kann man zukünftig eine Balance zwischen einer naturnahen Lebensweise in den Städten und den Bedürfnissen der Stadtbewohner erreichen?",
        "chinese": "未来，人们怎样才能在城市中的亲近自然的生活方式与城市居民的需求之间实现平衡？城市与 自然怎样才能尽可能合理地结合起来？在思考这些问题时，我自然而然地想到了各种解决办 法——因此，朝着正确的方向迈出几步应该并没有那么困难。 一种可能性当然是，未来把重要的设施和商店都建在所有居民附近，这样他们就可以不使用自 己的汽车或送货服务。雇主也可以作出自己的贡献：他们允许的居家办公越多，人们开车前往 工作地点的次数就越少。给新建建筑配备屋顶花园，也有助于改善城市气候。 但在我看来有一点也是确定的：我们迫切需要一个全面的环保城市规划方案，仅靠个人的努力 是不够的。",
        "sentenceZh": "未来，人们怎样才能在城市中的亲近自然的生活方式与城市居民的需求之间实现平衡？",
        "summary": "未来，人们怎样才能在城市中的亲近自然的生活方式与城市居民的需求之间实现平衡？",
        "passage": "Wie kann man zukünftig eine Balance zwischen einer naturnahen Lebensweise in den Städten und den Bedürfnissen der Stadtbewohner erreichen? Wie lassen sich Stadt und Natur möglichst sinnvoll miteinander vereinbaren? Beim Nachdenken über diese Punkte kommen mir spontan verschiedene Lösungsansätze in den Sinn – daher sollte es doch nicht so schwer sein, ein paar Schritte in die richtige Richtung zu gehen. Eine Möglichkeit wäre es gewiss, wenn wichtige Einrichtungen und Geschäfte zukünftig für alle Bewohner in unmittelbarer .Nähe erreichbar wären, sodass sie auf ein eigenes Auto oder Lieferdienste verzichten könnten. Auch die Arbeitgeber könnten ihren Teil leisten: Je mehr Home-Office sie ermöglichen, desto weniger Autofahrten zum Arbeitsplatz sind notwendig. Zu einem besseren Stadtklima würde es auch beitragen, Neubauten mit Dachgärten auszustatten. Sicher ist meines Erachtens aber auch: Es bedarf dringend eines umfassenden Konzepts zur umweltfreundlichen Stadtplanung, das Engagement Einzelner reicht nicht aus.",
