        "passage": "Einige positive Trends zeichnen sich heute zum Glück schon ab. So sind die Städte unter anderem dank moderner Technik sauberer geworden und werden auch als grüner empfunden. Doch das Ziel ist noch lange nicht erreicht. Damit umweltfreundliche Städte tatsächlich Wirklichkeit werden können, muss nun also dringend gehandelt werden! Die zuständigen Stadtplaner und Politiker sollten sich umgehend an einen Tisch setzen – dies muss zu ihrer Priorität werden! Natürlich sollte jeder Einzelne weiterhin versuchen, möglichst viel für eine umweltfreundlichere Gesellschaft zu tun, und es ist erfreulich, dass gerade die jungen Leute sich des Themas bewusst sind. Aber die Zeit läuft und es muss bald eine Lösung auf gesamtgesellschaftlicher Ebene gefunden werden.",
