        "text": "„Frau Gerolds Garten“ ist ein nettes Plätzchen.",
        "german": "„Frau Gerolds Garten“ ist ein nettes Plätzchen.",
        "firstSentence": "„Frau Gerolds Garten“ ist ein nettes Plätzchen.",
        "chinese": "女士的花园”是一个很不错的地方。在这家很受欢迎的花园餐厅里，聚集着许多向往自 然和绿色生活的年轻城市居民。80个高架种植床里生长着香草和蔬菜，在它们之间，一些年轻 的创意工作者和几个商务人士坐在扶手椅和长椅上，喝着瓶装啤酒。 有兴趣的人还可以立即报名参加一个制作昆虫旅馆的工作坊。如果您不知道这是什么：它指的 是人为给昆虫建造的住所和栖息地，昆虫可以在里面筑巢。 在这个越来越数字化的世界中，现代人也经常为自己寻找一个可以退避和休息的地方，而他们 在这里——这家宁静而且位于自然之中的餐厅——找到了这样的地方。也许亲爱的读者，您也 熟悉这种感觉，同样也在寻找这样一个避世之所。",
        "sentenceZh": "女士的花园”是一个很不错的地方。",
        "summary": "女士的花园”是一个很不错的地方。",
        "passage": "„Frau Gerolds Garten“ ist ein nettes Plätzchen. In dem beliebten Gartenlokal versammeln sich viele junge Städter, die die Sehnsucht nach Natur und Grün vereint. In achtzig Hochbeeten wachsen Kräuter und Gemüse, dazwischen sitzen junge Kreative und ein paar Geschäftsleute auf Sesseln und Bänken und trinken Bier aus der Flasche. Wer Lust hat, kann sich gleich für einen Workshop zum Bau von Insektenhotels anmelden. Falls Ihnen das kein Begriff ist: Es handelt sich dabei um von Menschen geschaffene Heime und Rückzugsorte für Insekten, in denen diese nisten können. Einen Rückzugsort sucht sich auch oft der moderne Mensch in der immer digitaler werdenden Welt und findet ihn hier in dem beschaulichen, mitten in der Natur gelegenen Lokal. Vielleicht kennen Sie, liebe Leserin und lieber Leser, dies auch und suchen ebenfalls ein solches Refugium. “Gerolds",
