        "number": "4",
        "paragraph": "D",
        "text": "Niemand zweifelt daran, dass der neue Trend zur Ökologie die Städte bereichert und attraktiver macht.",
        "german": "Niemand zweifelt daran, dass der neue Trend zur Ökologie die Städte bereichert und attraktiver macht.",
        "firstSentence": "Niemand zweifelt daran, dass der neue Trend zur Ökologie die Städte bereichert und attraktiver macht.",
        "chinese": "没有人怀疑，新的生态环保趋势丰富了城市生活，并且让城市变得更有吸引力。但是，这种趋 势确实也会在一定程度上产生负面后果，而在客观探讨这一问题时，这些后果也必须被考虑进 去。 例如，如果不惜一切代价、以牺牲机动车交通为代价来扩建自行车道，就可能产生问题。没有 机动车交通的城市乍看之下或许很有吸引力，但是再仔细考虑一下，人们就会发现，这可能会 产生其他问题。 例如，如果运输条件受到严重阻碍或限制，人们就可能会危及城市的物资供应。当然，一座城 市并不是完全依赖机动车交通，但是任何改变都需要长期规划，而且往往会产生很高的成本。",
        "sentenceZh": "没有人怀疑，新的生态环保趋势丰富了城市生活，并且让城市变得更有吸引力。",
        "summary": "没有人怀疑，新的生态环保趋势丰富了城市生活，并且让城市变得更有吸引力。",
        "passage": "Niemand zweifelt daran, dass der neue Trend zur Ökologie die Städte bereichert und attraktiver macht. Doch zum Teil gibt es tatsächlich negative Folgen, die bei einer objektiven Auseinandersetzung mit dem Thema eine Rolle spielen. Etwa, wenn die Radwege um jeden Preis auf Kosten des motorisierten Verkehrs ausgebaut werden sollen. Städte ohne motorisierten Verkehr mögen zwar auf den ersten Blick reizvoll erscheinen. Aber spätestens beim zweiten Hinsehen merkt man, dass damit weitere Probleme entstehen könnten. So würde man etwa die Versorgung der Städte aufs Spiel setzen, wenn die Transportmöglichkeiten stark erschwert oder eingeschränkt würden. Natürlich ist eine Stadt nicht allein vom motorisierten Verkehr abhängig, aber Änderungen bedürfen einer langen Planung und verursachen oft hohe Kosten.",
